export const PRODUCT = {

accounts_stores: {
  packages: ["consumergoods"],
  name: "Accounts & Stores",
  icon: "\u{1F3EA}",
  color: "#38bdf8",
  description: "Accounts and stores provide the customer and physical-location foundation for Retail Execution in Consumer Goods Cloud, including retailers, distributors, wholesalers, consumers, contacts, store groups, operating hours, and in-store locations. The enhanced model adds customer extensions, time-dependent trade org hierarchies, sales organizations, org units, customer sets, segmentation rules, assets, and points of sale for multi-market management. Store and customer data drives visit creation and scheduling, product assortments and promotions, route and tour destinations, territory maps, mobile synchronization, visit execution, shared TPM account hierarchies, and store-level analytics. The same context supports agents, feeds store attributes and targets to Einstein predictions, and is ingested into Data Cloud data model objects.",
  components: [
    {id:"retail-stores",name:"Retail Stores & Locations",icon:"\u{1F3EC}",desc:"Retail Stores & Locations represent the physical selling locations associated with retail business accounts in Consumer Goods Cloud. Store records can include location groups, operating hours, geographic coordinates, and in-store areas such as aisles, endcaps, and checkout counters. These records support store visits, map visualization, product availability, and store-level performance analysis.",tags:["RetailStore","InStoreLocation","RetailLocationGroup","OperatingHours","Location","TimeSlot","StoreProduct"],docs:["The Account object stores retail business account information, while the Retail Store object stores information about each physical store. Retail Store and Account have a master-detail relationship, so Retail Store can inherit sharing rules from Account and use Controlled by Parent as its sharing model. Visits and orders can be exposed on the Retail Store related list for store-level planning and review.","Operating Hours stores the time zone, business hours, and preferred visit hours for stores. Time Slot records define the start and end time for individual days and have a one-to-many relationship with Operating Hours. Retail Location Group records organize stores into clusters based on shared characteristics such as size, location, retail chain, or product location.","In-Store Location stores information about areas such as aisles, endcaps, and checkout counters. Store Product associates a product with a retail store or a specific in-store location, providing the store-level product context used by retail execution. Valid geographic coordinates are required to show stores in embedded maps and map-based visit planning."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.retail_concept_admin_store_manage.htm&language=en_US",connections:[{"planet":"visit_planning","desc":"Stores are the targets of planned visits"},{"planet":"products_assortments","desc":"Stores have product assortments and store products"}]},
    {id:"customer-master",name:"Customer Master Data",icon:"\u{1F4CB}",desc:"Customer Master Data centralizes account information, contacts, account roles, relationships, receivables, operating hours, templates, and user assignments. Account can represent a retailer, distributor, wholesaler, or consumer, while Customer Extension supplies additional classification, status, pricing configuration, and role information. This master data is required for order taking, visit management, and activity execution in Consumer Goods Cloud.",tags:["Account","cgcloud__Account_Extension__c","cgcloud__Account_Template__c","cgcloud__Account_Manager__c","cgcloud__Account_Receivable__c","Contact"],docs:["The Account object is the main object in the enhanced data model and stores information about customers with whom the manufacturer conducts business. Customer Extension adds account classification, status, complex pricing configuration, and account roles used in visits and promotions. Customer Template provides the details used to create accounts with consistent initial characteristics and roles.","Customer Relationship specifies operational roles between two customers, including Bill To, Delivery Recipient, Payee, Payer, and Wholesaler. A customer can have multiple relationships of one type but only one primary relationship for that type. Sub-Account is separate from these relationship roles and is used primarily in account planning so that subaccount KPIs can contribute to parent account KPIs.","Customer Manager represents user assignments to accounts through org units and supports retail operations such as order placement, visit creation, customer relationships, and team activities. AccountManagerOrgUnitBased can create or update customer managers from customer and user org unit assignments, while EffectiveAccountManagerSyncBatch creates account team members from valid customer managers. Customer Condition records can be used for customizations, but the Customer Condition object isn’t a part of the core calculations."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.cg_task_admin_create_customer.htm&type=5&language=en_US",connections:[{"planet":"visit_planning","desc":"Customer visit settings drive automated visit creation"},{"planet":"van_sales","desc":"Customers are delivery recipients on routes"}]},
    {id:"trade-org-hierarchy",name:"Trade Org Hierarchy",icon:"\u{1F3D7}",desc:"Trade Org Hierarchy represents time-dependent parent-child relationships between customer accounts. It supports planning retail activities at a parent level, with child accounts inheriting retail activities from the parent account. Consumer Goods Cloud also uses flattened hierarchy data in processes that require consistent access to hierarchy levels.",tags:["cgcloud__Account_Trade_Org_Hierarchy__c","cgcloud__Account_Relationship__c","cgcloud__Sub_Account__c"],docs:["Trade Org Hierarchy stores relationships between accounts as parent-child relationships and represents how accounts under a parent customer are organized. Each relationship is valid only for its defined time frame and can be associated with a sales organization. Retail activities can be planned at the parent level and inherited by child accounts.","Trade Org Hierarchy is distinct from Customer Relationship and Sub-Account. Customer Relationship defines operational roles such as Bill To, Delivery Recipient, Payee, Payer, and Wholesaler, while Sub-Account is used primarily in account planning. FlattenAccountHierarchyBatch flattens the account hierarchy for processes that require more uniform hierarchy access, including product authorization and promotion aggregation."],connections:[{"planet":"products_assortments","desc":"Product assortments inherit through the trade org hierarchy"}]},
    {id:"sales-organizations",name:"Sales Organizations",icon:"\u{1F310}",desc:"Sales Organizations are business segments used to structure Consumer Goods Cloud data and business processes by organizational unit. Segmentation can be based on geographic territory, product division, or account team. Sales organizations enable multi-market management for enhanced-model processes such as advanced visits, advanced orders, sales folders, and advanced promotions.",tags:["cgcloud__Sales_Organization__c","cgcloud__Sales_Organization_User__c"],docs:["A sales organization separates master data, templates, and advanced business processes within one Salesforce org. Master data is unique for each sales organization, and templates can group accounts, products, assortments, assets, tasks, and other business configurations by sales organization. Multi-market management supports a global template approach without requiring a separate Salesforce org for every market.","Sales Organization User associates a user with a sales organization. A mapped user can access data and work with activities, visits, or orders for that sales organization in the Consumer Goods Cloud Offline mobile app. Users can belong to multiple sales organizations for online work, but a user works in one default sales organization per session and belongs to only one Mobility Sales Org for mobile synchronization.","Multi-market management is supported out of the box only for advanced processes based on the enhanced data model. It isn’t supported out of the box for retail stores, assessment tasks, action plans, or retail store KPIs. Administrators create sales organization and business area picklist values before creating and assigning sales organization records."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.cg_admin_concept_sales_org.htm&type=5&language=en_US",connections:[{"planet":"products_assortments","desc":"Product templates and assortments belong to a sales org"},{"planet":"van_sales","desc":"Warehouses and routes belong to a sales org"}]},
    {id:"org-units",name:"Org Units & Territories",icon:"\u{1F5FA}",desc:"Org Units & Territories model the internal structure of an organization through physical territories or logical divisions. Org units can represent small organizational units such as departments or branches and can be arranged into time-dependent hierarchies. They connect customers and users to control access, synchronization, segmentation, supervision, substitutions, and regional processes.",tags:["cgcloud__Org_Unit__c","cgcloud__Org_Unit_Hierarchy__c","cgcloud__Org_Unit_User__c","cgcloud__Account_Org_Unit__c"],docs:["Org Unit records can represent physical territories for sales teams or logical units for service teams. Org Unit Hierarchy records define parent-child relationships between org units and include validity periods. Consumer Goods Cloud supports multiple org unit types within one sales organization.","Customer Org Unit associates an account with an org unit, and the sales organization of the account and org unit must match. Org Unit User assigns users such as sales reps or supervisors to an org unit and records their management relationship, such as sales or service. Multiple assignments can be maintained when validity periods, org unit types, or management responsibilities differ.","Org units control customer master synchronization, regional sales folders, regional promotions through customer segmentation, customer master access rights, supervisor teams, substitutions, and customer segmentation. AccountManagerOrgUnitBased recalculates customer managers from customer and user org unit assignments. EffectiveAccountManagerSyncBatch then uses valid customer managers to create account team members and provide account access."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.cg_concept_admin_org_units.htm&type=5&language=en_US",connections:[{"planet":"maps_territory","desc":"Org units define territory boundaries for map visualization"},{"planet":"visit_planning","desc":"Org units determine which reps can create visits for which customers"}]},
    {id:"customer-sets",name:"Customer Sets & Segmentation",icon:"\u{1F3AF}",desc:"Customer Sets & Segmentation group customers so activities, promotions, and pricing-related work can be planned at a group level. Customer sets can be created manually, integrated from an external system, or populated through segmentation rules. Segmentation definitions use SOQL filter criteria and can filter accounts through account or org unit hierarchy context.",tags:["cgcloud__Account_Set__c","cgcloud__Account_Set_Account__c","cgcloud__Account_Set_Manager__c","cgcloud__Segmentation_Rule__c","cgcloud__Segmentation_Rule_Def__c","cgcloud__Segmentation_Rule_Def_Column__c"],docs:["A Customer Set is a set of customers that perform similar activities, such as promotions, pricing, or retail activities. Customer Set Customer associates individual accounts with the set, while Customer Set Manager assigns users to the set and can support promotion sharing rules. Customer sets can also be assigned to activities and advanced promotions.","Segmentation Rule associates a Segmentation Rule Definition and an account with a customer set. Segmentation Rule Definition stores the SOQL query and indicates whether filtering uses the account hierarchy or org unit hierarchy. Segmentation Rule Definition Column defines fields and attributes used as placeholders in the rule definition.","Customer segmentation can create target groups for activities, visits, asset checks, or product-focused work without repeating planning for each account. Definitions must be released before they are used to create segmentation rules. Running the segmentation process evaluates the configured criteria and updates the associated customer set."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.cg_task_admin_create_customer_sets.htm&type=5&language=en_US",connections:[{"planet":"products_assortments","desc":"Customer sets target promotions to specific store groups"},{"planet":"visit_execution","desc":"Activities can be assigned to customer sets"}]},
    {id:"assets-pos",name:"Assets & Point of Sale",icon:"\u{2744}",desc:"Assets & Point of Sale support tracking manufacturer-owned equipment and secondary product-placement locations at customer sites. Assets can represent items of value such as refrigerators or coolers, while Point of Sale records represent locations other than the primary shelf. Audits and customer tasks connect observed asset conditions to repair, replacement, or service work.",tags:["Asset","cgcloud__Asset_Audit__c","cgcloud__Asset_Template__c","cgcloud__POS__c","cgcloud__POS_Template__c","cgcloud__Account_Task__c","cgcloud__Account_Task_Template__c"],docs:["Manufacturers can place assets such as refrigerators or coolers at customer locations and regularly track their condition. Asset Template defines the characteristics required to create an asset of a specific type. Asset Audit records the condition of an asset at the customer location and can be completed by sales reps during store visits.","When an asset audit identifies an issue, a customer-specific task can be created for repair, replacement, or service. Customer Task Template defines reusable task types such as complaints or service requests. Customer tasks are associated with the customer rather than a particular visit and can follow a configured workflow.","Point of Sale represents a location other than the primary shelf where products are placed for promotion or increased sales, such as a shelf, sales counter, freezer, or vending machine. POS Template defines the type of Point of Sale, such as a premium beverage or snack shelf. Questions and surveys can apply to a store, all points of sale in a store, or a POS type."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.cg_task_admin_create_asset_template.htm&type=5&language=en_US",connections:[{"planet":"visit_execution","desc":"Assets are audited and POS is inspected during visit execution"},{"planet":"mobile_app","desc":"Asset audit and POS inspection happens on mobile devices"}]},
    {id:"cg-sales-service",name:"CG for Sales & Service",icon:"\u{1F4DE}",desc:"CG for Sales & Service provides account-centered workspaces for sales and service agents in Consumer Goods Cloud. The apps give agents customer context for inquiries, orders, pricing, visits, and engagement history. Common capabilities include the Customer Profile card, Identity Verification, Action Launcher, Record Alerts, Timeline, Omni-Channel, and Salesforce Knowledge.",tags:["Account","Contact","cgcloud__Order__c"],docs:["Consumer Goods Cloud for Service gives service agents a 360-degree customer view for resolving cases, addressing complaints or inquiries, selling products, and placing regular orders. The service console can expose account details, visits, orders, pricing, and engagement history. Agents can use quick actions and Order Management Lightning Web Components to work with advanced orders.","Consumer Goods Cloud for Sales supports proactive outreach to lists of stores for regular orders, open invoices, promotions, product introductions, and other communications. Supervisors or sales managers create actionable lists and guidance for agents, and agents execute the prescribed actions during customer engagement. Actionable segmentation supports prioritizing, assigning, managing, and tracking these outreach lists.","The Customer Profile card shows store and store-manager information sourced from Account and Contact. Identity Verification supports predefined questions for confirming the identity of a customer, store manager, or authorized representative. Agents can also use simple pricing and Penny Perfect Pricing for orders, while Timeline and Engagement Interactions preserve chronological customer context."],connections:[{"planet":"products_assortments","desc":"Agents suggest products and promotions to customers"},{"planet":"visit_planning","desc":"Service agents can create visits for customers"}]}
  ],
  dataFlow: ["Create accounts, contacts, retail stores, location groups, operating hours, time slots, and in-store locations.","Enrich customer master data with extensions, trade org hierarchies, sales organizations, org units, customer sets, assets, and points of sale.","Associate stores and accounts with products, assortments, promotions, routes, tours, and delivery destinations.","Sync customer master data to mobile devices, use store and customer settings to create and schedule visits, and visualize stores by territory on maps.","Capture and enrich account and store data during visits, then use store attributes and targets for compliance analytics, performance analytics, Einstein predictions, and agent context.","Share account hierarchy context with TPM and ingest account and store data into Data Cloud data model objects."],
  connections: [{"planet":"visit_planning","desc":"Stores and customer settings drive visit creation and scheduling"},{"planet":"products_assortments","desc":"Stores have product assortments and promotions"},{"planet":"van_sales","desc":"Accounts are delivery destinations on routes and tours"},{"planet":"maps_territory","desc":"Stores are visualized on maps by territory"},{"planet":"mobile_app","desc":"Customer master data syncs to mobile devices"},{"planet":"visit_execution","desc":"Store and account data is captured and enriched during visits"},{"planet":"tpm_master_data","desc":"Customer master shares account hierarchies with TPM"},{"planet":"analytics","desc":"Store-level data powers compliance and performance analytics"},{"planet":"agentforce","desc":"Agents access store and account data for context"},{"planet":"einstein_ai","desc":"Store attributes and targets feed Einstein predictions"},{"planet":"data_cloud","desc":"Store and account data ingested into Data Cloud DMOs"}]
},

products_assortments: {
  packages: ["consumergoods"],
  name: "Products & Assortments",
  icon: "\u{1F4E6}",
  color: "#34d399",
  description: "Products & Assortments manages product master data, product hierarchies, logistical units, assortments, price books, condition records, and Sellable Promotions in Consumer Goods Cloud. Products can be organized with templates, parent-child hierarchies, product parts, units of measure, and warehouse assignments for ordering and distribution. Assortments determine product eligibility and listing behavior for accounts and stores, including optional closed-listing enforcement and listing modules for different store formats. Advanced promotions combine templates, tactics, hurdles, rewards, and sales folders for promotional execution in the Consumer Goods Cloud offline mobile app.",
  components: [
    {id:"product-master",name:"Product Master",icon:"\u{1F4E6}",desc:"Product Master manages the product information used by enhanced retail processes in Consumer Goods Cloud. Product2 records can represent sellable products or product groups and are related to product templates, product hierarchies, product parts, units of measure, product managers, and warehouses. Product templates and sales organizations support grouping products with similar characteristics by market, while product hierarchies organize products for orders, promotions, inventory, and surveys.",tags:["Product2","cgcloud__Product_Template__c","cgcloud__Product_Hierarchy__c","cgcloud__Product_Part__c","cgcloud__Unit_of_Measure__c","cgcloud__Product_Category_Share__c","PriceBook2"],docs:["Product2 stores product details and related information, including product parts, product conditions, units of measure, product managers, and warehouses. A product template is the blueprint for products with similar characteristics and is assigned to a sales organization. Product groups and individual products are both stored in Product2 and differentiated by record type and template. Product master data is generally interfaced from an ERP system, while users can maintain additional information such as attachments and competitor products in Consumer Goods Cloud.","Product Hierarchy represents how a manufacturer’s products are organized. It supports parent-child relationships between product groups and between a product group and one or more products. The dynamic hierarchy is used to identify, group, and search for products in retail execution processes, and the flattened hierarchy supports optimized access in scenarios such as Condition Search in Penny Perfect Pricing. A product is added to the hierarchy when a parent product or product group is assigned for a valid period.","Product Part records describe relationships between parent and child products, including the number of child products that make up the parent result. Unit of Measure records define logistical units for each product and are used to calculate product quantities during order taking. Multiple units can be configured for a product, including consumer, sales, layer, and pallet units, with settings for order ability, pricing, conversion, and quantity rounding. Warehouse Product associations identify products stored in warehouses for sales and delivery processes, including products loaded onto vehicles for Direct Store Delivery and Van Sales."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.cg_task_admin_create_product_templates.htm&type=5&language=en_US",connections:[{"planet":"visit_execution","desc":"Products are surveyed and ordered during visits"},{"planet":"van_sales","desc":"Products are stocked in warehouses for delivery"}]},
    {id:"product-assortments",name:"Product Assortments",icon:"\u{1F4CB}",desc:"Product Assortments define groups of products for purposes such as eligibility for sale in a specific store. Consumer Goods Cloud associates assortments with accounts, stores, or store groups and can use listing modules to account for different store formats. Assortment templates organize assortment types by sales organization, while validity periods determine which assortment and product assignments are applicable.",tags:["Assortment","AssortmentProduct","StoreAssortment","StoreProduct","cgcloud__Product_Assortment_Template__c","cgcloud__Product_Listing_Module__c","cgcloud__Listing_Module__c","cgcloud__Product_Assortment_Product_Share__c","cgcloud__Product_Assortment_Store__c"],docs:["An Assortment can contain products from multiple categories, and Assortment Product records identify products that are part of the assortment based on saleability and validity. Product Assortment Category, represented by cgcloud__Product_Assortment_Product_Share__c, associates product categories with an assortment; it does not add individual products. Product Listing Module records filter products by product category and store module definitions, allowing one assortment to support different formats within a trade organization chain. Listing modules can therefore distinguish products sold in formats such as hypermarkets from those sold in supermarkets.","StoreAssortment, also labeled Product Assortment Customer in the enhanced model, associates an assortment with an account, including a trade organization or store. Accounts in a trade organization hierarchy can inherit the assortment list of a parent account. By contrast, Product Assortment Store records are batch-created assignments that represent listing-finding results for valid assortments; they are not the primary records used to assign assortments to accounts. AuthorizationListSetupBatch searches the account hierarchy from the lowest level upward, stops at the first hierarchy level with valid lists, and writes valid store results to Product Assortment Store.","Assortments contribute products to order disposal lists when the applicable order template and assortment configuration require them. A closed listing applies only when Closed Listing is enabled and the applicable product assortments are obligatory; under that condition, products outside the listing can’t be added to the order. Without closed-listing configuration, products outside the listing can be added. Product and assortment data can also be mapped to Data Cloud data model objects for account segmentation and analysis."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.cg_concept_manage_advanced_product_assortments.htm&type=5&language=en_US",connections:[{"planet":"accounts_stores","desc":"Assortments are assigned to stores and accounts"},{"planet":"visit_execution","desc":"Assortments determine available products during order taking"}]},
    {id:"advanced-promotions",name:"Advanced Promotions",icon:"\u{1F3F7}",desc:"Advanced Promotions manages Sellable Promotions that use temporary price reductions, coupons, in-store displays, and other tactics to increase revenue and market share. Promotion templates determine the promotion type, while tactic templates control the behavior of the tactics created for a promotion. Promotions can be anchored to a customer or customer set and can include products at the tactic level.",tags:["cgcloud__Promotion__c","cgcloud__Promotion_Template__c","cgcloud__Promotion_Template_Hierarchy__c","cgcloud__Tactic__c","cgcloud__Tactic_Product__c","cgcloud__Tactic_Template__c","cgcloud__Promotion_Push_Status__c","cgcloud__Promotion_Template_Tactic_Template__c"],docs:["An Advanced Promotion represents an agreement between a manufacturer and a customer to increase revenue and market share through mechanisms such as temporary price reductions or in-store displays. A business admin creates a Promotion Template before a Key Account Manager creates promotions, and the same template can be reused for multiple promotions. Promotion Template Hierarchy supports extending or pushing promotions at different customer-hierarchy levels. Promotion Push Status stores the status and statistics for promotion push processes.","A tactic is the lowest action-oriented or procedural level in running a promotion. Tactic Template defines tactic behavior, Promotion Template Tactic Template associates eligible tactic templates with a promotion template, and Tactic Product assigns products and quantities at the tactic level. Promotions can be surfaced during visits, and promoted products can be included in order disposal lists when the corresponding order template settings apply. Product assortments also define the products available for Trade Promotion Management promotions that are transferred to Retail Execution.","Advanced promotions are used for promotional orders in the Consumer Goods Cloud offline mobile app. Relevant selectable promotions must be active, committed, valid for the current date, and assigned to the order customer. Consumer Goods Cloud can show promoted products and promotion filters in an order according to the order template configuration. Advanced promotions can’t be used in the Consumer Goods Cloud desktop app."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.cg_concept_admin_promotion_management.htm&type=5&language=en_US",connections:[{"planet":"visit_execution","desc":"Promotions are executed and measured during store visits"},{"planet":"accounts_stores","desc":"Promotions target customer sets and customer hierarchies"}]},
    {id:"promotion-hurdles",name:"Promotion Hurdles & Rewards",icon:"\u{1F3C6}",desc:"Promotion Hurdles & Rewards defines the criteria and benefits associated with Sellable Promotions in Consumer Goods Cloud. Promotion Hurdles and Promotion Hurdle Expressions evaluate thresholds, operators, survey responses, quantities, or values. Reward Groups organize applicable rewards and reward products, and rewards become available according to the results of hurdle and expression evaluation.",tags:["cgcloud__Promotion_Hurdle__c","cgcloud__Promotion_Hurdle_Expression__c","cgcloud__Promotion_Reward_Group__c","cgcloud__Promotion_Reward__c","cgcloud__Promotion_Reward_Product__c"],docs:["Promotion Hurdle defines parameters that are evaluated to assign a reward to a Sellable Promotion, and Promotion Hurdle Expression defines the evaluation criteria. Hurdles can be reward-group-specific or reward-specific. Reward-group-specific hurdles determine whether the group is fulfilled, while reward-specific hurdles add eligibility requirements for an individual reward. Promotion expressions can evaluate item quantities, item values, answered questions, or answered product surveys.","Promotion Reward Group contains the rewards assigned to a Sellable Promotion. Promotion Reward stores the reward details, and Promotion Reward Product identifies products assigned to a reward. Supported reward behavior includes special base price, percentage discount, amount per unit, flat rate, free item, and special rewards, according to the configured reward and Pricing Condition Template. Rewards can be automatically granted or selected according to reward multiplicity, subgroup, and hurdle results.","Hurdle and reward evaluation is supported for promotional orders in the Consumer Goods Cloud offline mobile app. When order contents or qualifying answers satisfy the configured expressions and hurdles, the applicable reward group and rewards become eligible, and configured automatic rewards can be applied. If a reward group becomes unsatisfied after an order change, Consumer Goods Cloud removes rewards that no longer apply. Advanced promotions, including this hurdle and reward behavior, aren’t supported in the Consumer Goods Cloud desktop app."],connections:[{"planet":"visit_execution","desc":"Hurdle evaluation happens during order pricing"}]},
    {id:"sales-folders",name:"Sales Folders",icon:"\u{1F4C2}",desc:"Sales Folders manage and publish content that supports sales reps during sales pitches. A Sales Folder is created from a Sales Folder Template and can be linked to a customer or an org unit. Sell Sheets group attachments within a folder, and Promotion Sales Folder links selling content to promotions.",tags:["cgcloud__Sales_Folder__c","cgcloud__Sales_Folder_Template__c","cgcloud__Sales_Folder_Sell_Sheet__c","cgcloud__Sell_Sheet__c","cgcloud__Promotion_Sales_Folder__c"],docs:["A Sales Folder Template is assigned to a sales organization and defines the template used to create Sales Folder records. Sales folders can be anchored to a customer or an org unit, depending on the template. Defining a sales folder at a higher level of a trade organization hierarchy or for an org unit makes the content available to relevant stores. In the Consumer Goods Cloud desktop app, only directly related sales folders are available, while hierarchy and org-unit searches are available in the Consumer Goods Cloud offline mobile app.","Sell Sheet records group attachments for use in sales folders, such as collections of event-specific videos or images. Sales Folder Sell Sheet associates a Sell Sheet with a Sales Folder and can specify its position within the folder. Promotion Sales Folder links a Sales Folder to an Advanced Promotion, supporting promotion-specific sales pitches. Sales folder content and supported attachments are synchronized to the Consumer Goods Cloud offline mobile app according to its sync configuration and applicable limits."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.cg_concept_retail_sales_folder_limit.htm&type=5&language=en_US",connections:[{"planet":"mobile_app","desc":"Sales folder content syncs to mobile app for offline access"}]},
    {id:"pricing-conditions",name:"Pricing & Conditions",icon:"\u{1F4B0}",desc:"Pricing & Conditions covers price books and the legacy condition records used to store product, customer, and customer-specific product pricing information. Product Conditions can determine product prices for orders, while Customer Conditions and Customer-Specific Product Conditions are available for customizations and aren’t part of the core calculations. Condition Templates define whether conditions reference customers, products, or both.",tags:["cgcloud__Product_Condition__c","cgcloud__Account_Condition__c","cgcloud__Account_Specific_Product_Condition__c","cgcloud__Condition_Template__c"],docs:["Each Product2 record can be tied to a price book entry that stores its list price, while PriceBook2 identifies the price book and whether it is active or standard. Legacy Condition objects store prices or discounts for customers, products, or customer-product combinations. Product Conditions can define multiple product prices based on price type, price list type, value, and validity. Customer Conditions and Customer-Specific Product Conditions can be imported from ERP systems and used in customizations, promotions, account plan calculations, or Processing Services configurations, but they aren’t part of the core calculations.","Condition Template defines condition behavior and whether the reference is a customer, a product, or both. This object is distinct from Pricing Condition Template, cgcloud__CP_Pricing_Condition_Template__c, which is used by Penny Perfect Pricing. In Penny Perfect Pricing, a Calculation Schema Step indicates the relationship between a calculation schema and a Pricing Condition Template; pricing-condition records aren’t assigned directly to calculation schemas. The Pricing Condition Template defines the condition type and calculation behavior and can reference a Search Strategy for finding applicable Complex Pricing Conditions.","Penny Perfect Pricing conditions are staged in Pricing Condition Stage and Pricing Condition Scale Stage and processed into Complex Pricing Condition records for order calculation and mobile synchronization. The primary system for these pricing conditions is external. This complex-pricing mechanism is separate from cgcloud__Condition_Template__c, cgcloud__Account_Condition__c, and cgcloud__Account_Specific_Product_Condition__c. Administrators should therefore configure the appropriate condition model for the intended calculation or customization rather than treating the legacy Condition objects as Penny Perfect Pricing inputs."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.cg_concept_admin_advanced_pricing.htm&type=5&language=en_US",connections:[{"planet":"visit_execution","desc":"Pricing conditions drive order calculations during visits"},{"planet":"accounts_stores","desc":"Customer conditions apply per account or customer set"}]}
  ],
  dataFlow: ["Create product templates, products, hierarchies, parts, and units of measure, and assign products to warehouses for vehicle loading.","Maintain price books and the applicable legacy or Penny Perfect Pricing configuration without conflating their condition models.","Build assortments, add saleable products and product categories, apply listing modules, and assign assortments to accounts and stores.","Use active listings during visits to survey, promote, and order products, enforcing product-only ordering only when closed listing is configured.","Configure Sellable Promotions with tactics, hurdles, rewards, and sales folders, and make assortment products available to Trade Promotion Management promotions.","Sync product data and sales folders to mobile devices, and map product and assortment data to Data Cloud data model objects."],
  connections: [{"planet":"accounts_stores","desc":"Products and assortments are assigned to stores and accounts"},{"planet":"visit_execution","desc":"Products are ordered, surveyed, and promoted during visits"},{"planet":"van_sales","desc":"Products are stocked in warehouses and loaded onto vehicles"},{"planet":"mobile_app","desc":"Product data and sales folders sync to mobile devices"},{"planet":"promotions","desc":"Product assortments define available products for TPM promotions"},{"planet":"data_cloud","desc":"Product and assortment data mapped to Data Cloud DMOs"}]
},

visit_planning: {
  packages: ["consumergoods"],
  name: "Visit Planning",
  icon: "\u{1F4C5}",
  color: "#a78bfa",
  description: "Visit Planning in Consumer Goods Cloud creates visits for accounts and retail stores through manual planning, Customer Visit Setting automation, Job Lists, Trip Lists, multiple-visit actions, advanced maps, and the Consumer Goods Cloud offline mobile app. Visit Templates define visit types and control duration, mobile availability, synchronization, GPS and time capture, geofencing, and execution rules before planned visits are assigned to field reps. Advanced maps support map-based visit creation and route optimization, while routes and tours organize Direct Store Delivery and van-sales visits; Einstein visit recommendations help identify stores to prioritize. Customer Service Assistance provides the Visit Management topic for scheduling, while Retail Execution Visit Assistant supplies account performance, compliance, visit-history, order, and product-upsell insights that can inform planning.",
  components: [
    {id:"visit-templates",name:"Visit Templates",icon:"\u{1F4DD}",desc:"Visit Templates define customer visit types in Consumer Goods Cloud, such as sales visits, training, delivery visits, merchandising visits, service visits, phone calls, and van sales visits. They control visit duration, user roles, creation platform, mobile relevance, synchronization behavior, GPS and time capture, and deletion or cancellation rules. They also configure historical-product handling, media capture, overlap checks for automatic visit planning, and geolocation validation for starting or completing visits.",tags:["cgcloud__Visit_Template__c","Visit"],docs:["A Visit Template is the reusable configuration used to create a customer visit type. Only active templates can be used to create visits, and the assigned sales org and user roles determine where and by whom the template can be used. The Meta Type controls the visit category and the icon presented on mobile devices. Default Duration supplies the planned visit duration in minutes.","Creation Platform determines whether a template is available in the Consumer Goods Cloud offline mobile app, the Consumer Goods Cloud app, or both, while Mobility Relevant determines whether template-created visits can be used on mobile devices. Sync Options can trigger background synchronization when a visit is completed, canceled, or either completed or canceled. Templates can also control whether users may delete visits, whether a cancellation reason is required, and whether jobs can be added manually in the desktop or online mobile experience. The Check Overlap setting validates overlapping planned visits during automatic visit planning in the desktop app, but it doesn’t apply to the offline mobile app or other planning options.","Capture Proceeding Time records visit timing, while Location Capture at Start, Location Capture at Complete, and Location Capture at Cancel control GPS collection at key visit milestones. Start Visit Geolocation Validation and Complete Visit Geolocation Validation can apply no validation, show a warning, or prevent the action when the user is outside the sales organization’s configured geofence. Start Visit Required to Check In can require a user to start a visit before modifying or executing it, and Limit to One Visit In Progress prevents parallel visit execution. These enhanced geofencing and explicit-start settings apply to customer-related visits in the Consumer Goods Cloud offline mobile app.","Historical Products determines whether products surveyed in earlier visits are considered for a new survey, either across all prior visits or only visits with the same template meta type. Media settings can retain the date, time, and GPS coordinates associated with captured media and define a deviation threshold. Max. Number of Pictures controls how many pictures users can capture and attach to a visit, with the documentation recommending a value no greater than 10. KPI Relevant identifies the KPIs to capture during a visit."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.retail_concept_admin_whatsvisit.htm&language=en_US",connections:[{"planet":"visit_execution","desc":"Visit templates control what activities are available during execution"},{"planet":"van_sales","desc":"Delivery visit templates are used for DSD tours"}]},
    {id:"automatic-visits",name:"Automatic Visit Creation",icon:"\u{2699}",desc:"Automatic Visit Creation uses Customer Visit Setting information to plan visits for an account and user. The enhanced model lists automatic visit creation alongside manual visits, Job Lists, Trip Lists, and multiple-visit creation. Visit Template rules, account assignments, operating hours, and user settings provide planning context for the resulting visits.",tags:["cgcloud__Account_Visit_Setting__c","Visit"],docs:["Customer Visit Setting stores account configuration information used to plan an automated visit by a user. Its configuration associates the account with a Visit Template and can record the visit frequency and preferred day. The resulting Visit record represents the tasks or operations that a field rep carries out during a store visit. Advanced visits created for an account are visible and executable only to users assigned to that account.","Visit Templates supply rules that apply to automatically planned visits, including the default duration and Auto Status. The Check Overlap setting checks planned visits for conflicts during automatic visit planning in the Consumer Goods Cloud desktop app. Operating Hours holds store operating-hour information, while user sales-organization settings provide working days and work start and end times. Planned visits can then be synchronized to the Consumer Goods Cloud offline mobile app for field use."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.cg_admin_create_calls_automatically.htm&type=5&language=en_US",connections:[{"planet":"accounts_stores","desc":"Visit settings are defined per account"},{"planet":"maps_territory","desc":"Map-based visit creation uses store locations"}]},
    {id:"action-plan-templates",name:"Action Plan Templates",icon:"\u{1F4CB}",desc:"Action Plan Templates organize predefined work for standard visits in the Consumer Goods Cloud base data model. An action plan can be associated with a Visit, and a StoreActionPlanTemplate associates an Action Plan Template with a retail store. Action plans aren’t assigned to advanced visits, and a standard visit supports one assigned action plan.",tags:["ActionPlanTemplate","StoreActionPlanTemplate"],docs:["Sales managers create an Action Plan Template as part of manually setting up standard store visits. They then create a Visit and associate an action plan with that visit. StoreActionPlanTemplate provides the association between an Action Plan Template and a store. In the base model, action plans can contain supported retail tasks, including delivery tasks and signature tasks.","Action plans apply only to standard visits and aren’t assigned to advanced visits. Consumer Goods Cloud allows one action plan to be assigned per visit. Task dependencies aren’t supported in an Action Plan Template. For enhanced-model page configuration, the Action Plan List component can be added to the Visit record page so users can add action plans to visits.","Consumer Goods Cloud also supports flows as activities in Action Plan Templates. Admins can create flows for activities such as product demonstrations when the standard task types don’t cover the required process. Sales managers can add those flows to Action Plan Templates and ultimately to visits. Users require appropriate flow permissions to run them."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.retail_concept_admin_actionplantemp.htm&language=en_US",connections:[{"planet":"visit_execution","desc":"Action plans define the assessment tasks performed during visits"},{"planet":"accounts_stores","desc":"Action plan templates are associated with stores"}]},
    {id:"activities-job-lists",name:"Activities & Job Lists",icon:"\u{1F4DA}",desc:"Activities and Job Lists define questions, surveys, and other jobs that users complete during Consumer Goods Cloud visits. Standard activities can be reused across customers and visits, while event-driven activities are valid for a defined event or promotion period and run once during that period. Activity Templates can apply to specific customers, customer sets, or products, while a field sales activity can be mapped to customers, products, and Visit Templates.",tags:["cgcloud__Job_Definition_List__c","cgcloud__Job_Definition_List_Template__c","cgcloud__Job_Definition_Template__c","cgcloud__Job_Template__c","cgcloud__Job_List__c","cgcloud__Data_Type__c"],docs:["A Job Template determines whether an activity is a question or a survey and defines its behavior and visibility in the Consumer Goods Cloud offline mobile app. Job Definition Templates define the information to gather for a store or product, and Data Type specifies the answer format. An Activity Template contains a preconfigured list of Job Definition Templates and identifies whether activities created from it are standard or event-driven. Activity Templates can be applicable to specific customers, customer sets, or products.","A field sales activity contains multiple job definition lists. The activity can be mapped to different customers, products, and Visit Templates; Visit Template targeting belongs to the activity rather than the Activity Template. Standard activities are longer-lived to-do lists that can be added to visits for different customers and run multiple times. Event-driven activities are associated with an event or ongoing promotion for a defined time frame and can run only once during that period.","Job Lists primarily support event-driven activities. A Job List associates an activity with a Visit Template for a particular customer and can then be added to visits. The GenerateJobListBatch creates Job Lists from event-driven activities, and the enhanced-model workflow includes updating Job Lists after activities are created. During execution, Visit Job records store responses to questions or survey questions."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.cg_task_admin_create_activity.htm&type=5&language=en_US",connections:[{"planet":"visit_execution","desc":"Activities and job lists drive data capture during visit execution"},{"planet":"products_assortments","desc":"Event-driven activities are linked to promotions"}]},
    {id:"trip-lists",name:"Trip Lists & Scheduling",icon:"\u{1F5D3}",desc:"Trip Lists support visit creation and scheduling in the Consumer Goods Cloud enhanced data model. Supervisors can create visits by using Trip Lists on desktop or create Trip Lists in the Consumer Goods Cloud offline mobile app. User working times and working days provide scheduling context, while planned visits are later executed by assigned field reps.",tags:["Visit","cgcloud__Visit_Template__c"],docs:["Consumer Goods Cloud includes Trip List Planning as a Visit list-view action in the enhanced model. Admins add Trip List Planning to the Visit list-view button layout along with Advanced Visit, Visit Planning, Multiple New Visits, and Job List Planning. The documented visit-management workflows include creating visits by using Trip Lists on desktop and creating Trip Lists in the Consumer Goods Cloud offline mobile app. Trip Lists are therefore one of several supported visit-creation paths rather than a replacement for Visit records or Visit Templates.","Sales Organization User settings provide Work Begins, Work Ends, and weekday availability. The work start time applies to Visit Planning using Trip List and Multiple Visits, and the work end time also applies to these planning methods. Salesforce Calendar can display visits as events so sales managers can see assigned visits and avoid scheduling conflicts. Field reps can use their calendars to review scheduled visits and plan their day.","Advanced maps provide another planning path alongside Trip Lists. They support efficient visit planning and route optimization, and map-created visits use the Visit object with configured defaults for Visit Template and Place ID. For delivery operations, routes define sequenced customer stops and can create executable tours with corresponding visits. Tours can also be created independently and used for van-sales or delivery work."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.cg_admin_create_calls_trip_lists.htm&type=5&language=en_US",connections:[{"planet":"maps_territory","desc":"Trip lists can be optimized using Salesforce Maps routing"},{"planet":"mobile_app","desc":"Trip lists and ad-hoc visits are created on the mobile app"}]},
    {id:"substitution-management",name:"Substitution Management",icon:"\u{1F504}",desc:"Substitution Management designates substitute users to perform customer-related work when the primary user is unavailable. A substitution can apply for a defined validity period and can cover one or multiple customers and substitute users. This continuity supports operations such as visit planning and order capture during planned or unplanned absences.",tags:["cgcloud__Substitution__c","cgcloud__User_Setting__c"],docs:["The Substitution object manages planned and unplanned absences of sales reps. Users can assign one substitute to one customer, multiple substitutes to one customer, or one substitute to multiple customers. Substitution records identify the original user, substitute user, applicable account, and validity period. The same object stores substitution and customer-substitution records and distinguishes them through Record Type.","When creating a substitution, the user provides the substituted user, substitution type, validity period, and lead and follow-up access periods. Substitutes can review and plan visits for assigned customers on behalf of the substituted user. Org units support substitutions as part of customer access and team synchronization. Account-manager records ensure that the appropriate customer relationships are available for the substitution period.","The CGCloud : Manager to Customer based on Substitution Flow manages activation, deactivation, and timeframe changes for Substitution records. It calls CreateEditSubstitutionController to process each of those scenarios and create the appropriate account-manager records for substituted accounts. Starting Spring ’25, the OvrideSharingForSubstTeamMbr system setting supports activation of a current-date account substitution without full privileges to add account team members. The user activating the substitution must still be the customer manager for the related account."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.cg_concept_admin_substitutionmanagement.htm&type=5&language=en_US",connections:[{"planet":"accounts_stores","desc":"Substitutions are assigned per customer"},{"planet":"visit_execution","desc":"Substitute reps execute visits on behalf of absent reps"}]}
  ],
  dataFlow: ["Configure Visit Templates, account visit settings, activities, Job Lists, user schedules, and substitutions.","Prioritize accounts and retail stores with business needs and Einstein visit recommendations.","Create visits manually, automatically, from Job Lists or Trip Lists, with multiple-visit actions, or through advanced maps and the Consumer Goods Cloud offline mobile app.","Assign visitors, schedules, action plans for standard visits, and DSD tour or route context for delivery visits.","Synchronize planned visits to the Consumer Goods Cloud offline mobile app and execute them with field reps.","Review visit status, timing, location, and history, and use Agentforce insights or Visit Management to support follow-up planning."],
  connections: [{"planet":"accounts_stores","desc":"Visits target accounts and retail stores"},{"planet":"visit_execution","desc":"Planned visits are executed by field reps"},{"planet":"maps_territory","desc":"Map-based visit creation and route optimization"},{"planet":"mobile_app","desc":"Visit planning and ad-hoc visits available on mobile"},{"planet":"van_sales","desc":"Delivery visits are planned for DSD tours"},{"planet":"agentforce","desc":"Visit Assistant supports field rep visit planning"},{"planet":"einstein_ai","desc":"Einstein recommendations influence visit planning priorities"}]
},

visit_execution: {
  packages: ["consumergoods"],
  name: "Visit Execution",
  icon: "\u{2705}",
  color: "#f472b6",
  description: "Visit Execution is the Consumer Goods Cloud domain where field reps carry out planned or ad hoc retail visits, primarily in the Consumer Goods Cloud offline mobile app. It covers assessment tasks and KPIs, questions and surveys, advanced ordering with Penny Perfect Pricing, Direct Store Delivery inventory activity, daily reports, signatures, approvals, and workflow automation. The base model uses standard visits with action plans, while the enhanced model adds template-based advanced visits, advanced business processes, sales-organization segmentation, GPS tracking, and offline execution. Visit results enrich account and store records and support territory views, CRM Analytics, Data Cloud, Agentforce, and Einstein capabilities.",
  components: [
    {id:"assessment-tasks",name:"Assessment Tasks & KPIs",icon:"\u{1F4CA}",desc:"Assessment Tasks & KPIs define and capture the retail activities and compliance measures that field reps complete during visits in Consumer Goods Cloud. Assessment Indicator Definition records establish metrics and their data types, while Retail Store KPI records define targets for stores, products, categories, promotions, assets, and in-store locations. Assessment Task Definition records describe planned activities, and Assessment Task and Retail Visit KPI records capture execution and actual results. In the base model, action plans assign supported tasks to standard visits.",tags:["AssessmentIndicatorDefinition","AssessmentTask","AssessmentTaskDefinition","AssessmentTaskIndDefinition","RetailStoreKpi","RetailVisitKpi","AssessmentTaskContentDocument"],docs:["Assessment Indicator Definition stores KPIs or metrics and identifies whether each metric uses numerical, decimal, text, date-time, or Boolean data. Retail Store KPI applies those metrics to retail stores and can define targets for products, product categories, promotions, installed assets, and planograms. Common definitions can also be applied across store groups and in-store location categories. Retail Visit KPI records the actual information collected during a visit against the applicable indicator and target.","Assessment Task Definition stores the name, description, category, and type of a retail activity defined by a sales manager. The corresponding Assessment Task represents the activity performed by a field rep in the field, and AssessmentTaskIndDefinition associates a task definition with its assessment indicators. Content documents can be associated with tasks through AssessmentTaskContentDocument. AssessmentTaskOrder represents an order activity that a sales rep can perform during a store visit.","In the base model, sales managers create Retail Store KPI records, Assessment Task Definition records, action plan templates, and visits before associating an action plan with a standard visit. Action plans are assigned only to standard visits, not template-based advanced visits. On the base-model offline experience, supported assessment tasks are Inventory Check and Custom or Other tasks. Task status can be updated by standard components or custom components that communicate with the Retail Execution runtime."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.retail_concept_admin_retailstorekpi.htm&language=en_US",connections:[{"planet":"visit_planning","desc":"Assessment task definitions are bundled into action plan templates"},{"planet":"accounts_stores","desc":"KPI targets are defined per store group via retail store KPIs"}]},
    {id:"advanced-orders",name:"Advanced Orders & Pricing",icon:"\u{1F6D2}",desc:"Advanced Orders & Pricing supports direct and indirect order taking, multiple order types, configurable order and item behavior, and Penny Perfect Pricing in Consumer Goods Cloud. Advanced orders use templates and the first applicable assortment in the time-dependent account hierarchy, while promotions can contribute promoted products, discounts, rewards, and free items. Penny Perfect Pricing applies calculation schemas, pricing condition templates, search strategies, key types, and pricing conditions to calculate order and item prices. Advanced ordering is available online and offline, with field execution supported through the Consumer Goods Cloud offline mobile app.",tags:["cgcloud__Order__c","cgcloud__Order_Item__c","cgcloud__Order_Template__c","cgcloud__Order_Item_Template__c","AssessmentTaskOrder","cgcloud__CP_Calculation_Schema__c","cgcloud__CP_Pricing_Condition_Template__c","cgcloud__CP_Pricing_Condition__c","cgcloud__CP_Key_Type__c","cgcloud__CP_Search_Strategy__c","cgcloud__CP_Key_Attribute__c","cgcloud__System_Number__c"],docs:["Order templates define the characteristics of standard orders, returns, advertising material orders, delivery documents, truck-load documents, and cash documents. They control behavior such as delivery-date calculation, disposal-list composition, quantity rounding, pricing mode, inventory references, order-number generation, and workflow assignment. Order item templates define how standard products, samples, returns, empty products, and free items behave within an order. Product assortments, historical products, promoted products, out-of-stock products, and specialized assortments can contribute products to the disposal list according to template configuration.","Penny Perfect Pricing uses a calculation schema containing an ordered sequence of calculation steps. Each step can reference a Pricing Condition Template, whose search strategy and key types determine how relevant base prices, discounts, surcharges, scales, free goods, and other conditions are found. The pricing engine can calculate manually through Offline (Button) or automatically through Offline (Edit Mode), depending on the order template. The primary system for pricing conditions is external, and staging records are condensed into Complex Pricing Condition records for efficient use by the mobile app.","Advanced order pricing results can be persisted for reporting and document output. Order header pricing fields include Gross Total Value, Gross Total Value Receipt, Total Value, Total Value Receipt, Merchandise Value Receipt, and Pricing Info fields. Order-item pricing fields include Base Price, Value, Special Price Receipt, Price, Special Price, Price Receipt, Value Receipt, Base Price Receipt, Gross Value Receipt, and Pricing Info fields. The advanced order lifecycle uses the Phase field.","Direct Store Delivery and Van Sales use advanced orders for delivery documents, van-sales orders, returns, payments, and inventory movements. Released check-out, delivery, and van-sales documents can create inventory transactions based on configured inventory references and templates. Promotions and assortments remain subject to the documented order and DSD rules; DSD and hybrid tours don’t support inclusion of promotions or promotional products in orders and documents. Advanced order execution in the field is supported by the Consumer Goods Cloud offline mobile app."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.cg_concept_admin_order_management.htm&type=5&language=en_US",connections:[{"planet":"products_assortments","desc":"Orders use product assortments and pricing conditions"},{"planet":"van_sales","desc":"Van sales orders are placed during delivery tours"}]},
    {id:"visit-jobs",name:"Visit Jobs & Surveys",icon:"\u{1F4DD}",desc:"Visit Jobs & Surveys supports questions, product surveys, store audits, and activity execution during visits in Consumer Goods Cloud. Job templates determine whether an activity is a question or a survey, while Job Definition Template records define the information to collect and its answer format. Activity templates group job definitions into standard or event-driven activities and can target customers, customer sets, products, and visit templates. Visit Job records store responses captured during visit execution.",tags:["cgcloud__Visit_Job__c","cgcloud__Historic_Product__c","cgcloud__Field_Sales_Activity__c"],docs:["A job template controls the behavior and visibility of activities in the Consumer Goods Cloud offline mobile app and determines whether the activity is a question or a product-referenced survey. Job Definition Template records define specific store or product questions, such as whether advertising material is present, how many shelves are available, whether products are correctly placed, or whether a promotional price is offered. Data Type and Data Type Option records configure supported answer formats and picklist choices. Questions can apply to stores or points of sale, while surveys collect product-related information.","Activity templates contain preconfigured lists of Job Definition Template records and determine whether created activities are standard or event-driven. Standard activities are reusable to-do lists that can run repeatedly for multiple customers, while event-driven activities are associated with an event such as a promotion and run during a defined period. Activities can be assigned to individual customers, customer sets, products, and visit templates. Job lists associate event-driven activities with visits for particular customers.","During visit execution, field reps answer the questions and surveys assigned to the visit. Visit Job stores the resulting responses, and Historic Product records retain products added during surveys so they can be reused in future visits. Survey and store-audit execution in the enhanced model is supported in the Consumer Goods Cloud offline mobile app. Survey results can also provide data for customer segmentation and downstream analytics."],connections:[{"planet":"visit_planning","desc":"Visit jobs correspond to activities and job definition templates"},{"planet":"mobile_app","desc":"Survey responses are captured offline on mobile devices"}]},
    {id:"daily-reports",name:"Daily Reports",icon:"\u{1F4C6}",desc:"Daily Reports track productive and unproductive time for sales reps in Consumer Goods Cloud. Daily Report Template records control workflow, creation platform, mobility relevance, activity-duration checks, and maximum activity duration. Daily Report Activity records identify the activities against which a rep logs time. Depending on template configuration, a report can also contain time derived from visit data.",tags:["cgcloud__User_Document__c","cgcloud__User_Document_Activity__c","cgcloud__User_Document_Template__c","cgcloud__User_Document_Template_Activity__c"],docs:["A daily report tracks the activities completed by a sales rep during a day. Daily Report Template defines the report workflow, supported creation platform, record type, sort order, mobility relevance, and duration controls. Daily Report Template Activity records add the activities for which time must be tracked. The associated workflow governs transitions such as Initial, Released, accepted, or rejected.","At the end of a day, a sales rep enters time spent on configured activities such as customer tasks, depending on the daily report template. Consumer Goods Cloud can also provide automatic time-utilization details based on visit data for the day. The rep releases the report before a supervisor can approve or reject it. If rejected, the report can be modified and submitted again through its configured workflow.","Daily reports support analysis of productive time spent on customer visits and unproductive time spent on activities such as breaks, training, vacation, or private appointments. Supervisors can use this information to monitor team time utilization. Daily report records and activities provide the operational source for that analysis rather than establishing that every report is completed before each visit ends."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.cg_concept_user_daily_report.htm&type=5&language=en_US",connections:[{"planet":"mobile_app","desc":"Daily reports are created and maintained on the mobile app"}]},
    {id:"signatures",name:"Signatures & Approvals",icon:"\u{1F58A}",desc:"Signatures & Approvals provides signed confirmation and controlled authorization for orders, deliveries, contracts, daily reports, and other supported business processes in Consumer Goods Cloud. Signature templates define general characteristics, attribute sets, location capture, mobility relevance, and sales organization. Signature Flow Step records define the required sequence and signing function, while Signature Attribute records retain values displayed with a signature. Approval processes and approval codes add authorization for order and Direct Store Delivery transactions.",tags:["cgcloud__Signature__c","cgcloud__Signature_Template__c","cgcloud__Signature_Flow_Step__c","cgcloud__Signature_Attribute__c","cgcloud__Approval_Code__c"],docs:["Signature Template defines characteristics such as description, sales organization, attribute set, automatic printing, mobility relevance, and whether the user’s location is captured. Signature Flow Step records identify the required signing sequence through Sort and identify the signing function through Function, such as cashier, checker, customer, guard, co-driver, or mobile user. Signature records associate the captured signature with its template, flow step, user, order, tour, or customer. Signature Attribute records store named values such as Name, Customer Id, and Amount for display during order taking or review.","Signatures can be captured during processes such as orders, contracts, daily reports, inventory check-out, and delivery execution. For orders, a template can require signature capture as part of release, and captured signatures can be synchronized and included in invoice output. If Capture Location is selected, latitude and longitude are stored during signature capture even when they aren’t displayed in the UI. Signature images can be synchronized in supported image formats.","Approval processes let supervisors approve, reject, or reassign supported business transactions, including customer tasks, time reports, and specified order types. The CGCloud : Order Approval for Mobility Flow submits eligible mobile orders for approval when Mobility Release is true. For Direct Store Delivery, approval codes authenticate critical transactions such as inventory check-out or cash check-in for warehouse checkers or cashiers. Approval history isn’t available for orders when Penny Perfect Pricing is enabled."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.cg_concept_admin_signature_management.htm&type=5&language=en_US",connections:[{"planet":"van_sales","desc":"Signatures are required for delivery confirmations and cash handling"},{"planet":"mobile_app","desc":"Signatures are captured on mobile device touchscreens"}]},
    {id:"workflows",name:"Workflows & Automation",icon:"\u{1F504}",desc:"Workflows & Automation controls lifecycle transitions and automates retail execution processes in Consumer Goods Cloud. A workflow is configured for one Usage, such as Promotion, Activity, Customer Tasks, Daily Reports, Contract Payments, or Order Entry, and belongs to a sales organization. Workflow State Transition records define allowed changes between business-process states and can restrict who performs them. Salesforce Flow and managed overridable flows automate repetitive operations such as mobile order approval and inventory-transaction currency updates.",tags:["cgcloud__Workflow__c","cgcloud__KPI_Set__c"],docs:["Workflow records define the lifecycle used by supported business processes. When creating a workflow, an administrator selects its Usage, sales organization, and description. A single workflow can’t be assigned to multiple business processes at the same time. Workflow State Transition records specify the current and destination states, whether the transition starts from the initial state, and the event that performs the transition.","Order templates can reference workflows that manage order approval and expose a Release action when the order can move to the next state. Daily report templates and customer task templates can also reference workflows to control review and approval. Workflow transitions identify responsible users as records move through configured states. Sales organizations segregate these advanced business-process configurations for multi-market implementations.","Consumer Goods Cloud includes managed overridable flows for selected automation scenarios. Examples include CGCloud : Order Approval for Mobility Flow, which submits mobile orders for approval, and CGCloud : Populate Inventory Transaction Currency Flow, which aligns transaction currency with its inventory. Consumer Goods Cloud also provides flows for account-extension synchronization, payment generation, contract responsibility, and substitution handling. Legacy workflows and Process Builders have mapped flows to support phased migration to Flow."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.cg_task_admin_create_workflow.htm&type=5&language=en_US",connections:[{"planet":"visit_planning","desc":"Workflows automate visit lifecycle state transitions"}]}
  ],
  dataFlow: ["Receive planned visits and activities from visit planning, or create an authorized ad hoc visit, and use Retail Execution agents to guide task completion.","Execute assessment tasks, KPIs, questions, surveys, inventory checks, and GPS-aware visit steps primarily in the Consumer Goods Cloud offline mobile app.","Build orders from applicable assortments and promotions, calculate prices with Penny Perfect Pricing, and process delivery orders or inventory updates during Direct Store Delivery execution.","Synchronize visit results, signatures, approvals, workflow updates, and end-of-day report data to Consumer Goods Cloud to enrich account and store records.","Feed GPS and compliance results to territory views, publish execution metrics to CRM Analytics and Data Cloud, and use the accumulated data with Agentforce and Einstein capabilities."],
  connections: [{"planet":"visit_planning","desc":"Planned visits and activities are executed by field reps"},{"planet":"products_assortments","desc":"Orders use assortments, promotions drive pricing"},{"planet":"van_sales","desc":"Delivery orders and inventory updates during DSD execution"},{"planet":"mobile_app","desc":"Visit execution happens primarily on the offline mobile app"},{"planet":"accounts_stores","desc":"Visit data enriches account and store records"},{"planet":"maps_territory","desc":"Visit GPS data and compliance metrics feed territory views"},{"planet":"analytics","desc":"Visit execution metrics feed CRM Analytics dashboards"},{"planet":"agentforce","desc":"Retail Execution agents guide in-store task completion"},{"planet":"einstein_ai","desc":"Visit execution data trains and validates Einstein models"},{"planet":"data_cloud","desc":"Visit execution data flows into Data Cloud for unified analytics"}]
},

van_sales: {
  packages: ["consumergoods"],
  name: "Van Sales & DSD",
  icon: "\u{1F69A}",
  color: "#fb923c",
  description: "Van Sales & DSD in Consumer Goods Cloud supports routes, tours, warehouses, vehicles, inventory, payments, and delivery documents for direct delivery and van sales operations. Routes organize customer accounts into ordered stops and can support map-based planning, while tours turn route plans or tour templates into executable trips that can span more than one day. Drivers perform visit-based orders, deliveries, returns, payment collection, and inventory activities through the Consumer Goods Cloud offline mobile app. Warehoused products and assortments support ordering, visit and tour schedules feed visit planning, and product velocity insights can inform vehicle loading.",
  components: [
    {id:"routes",name:"Routes & Route Management",icon:"\u{1F6E3}",desc:"Routes & Route Management defines reusable blueprints for delivery, sales, and merchandising trips in Consumer Goods Cloud. A route specifies characteristics such as warehouses, a default user, and vehicles, and associates customer accounts in an ordered stop sequence with visit types. Routes can be visualized during planning and used to create executable tours that feed route stops into visit planning.",tags:["cgcloud__Route__c","cgcloud__Route_Account__c","cgcloud__Route_Template__c"],docs:["A route defines the key characteristics of a trip, including its start and end warehouses, default driver, truck, and trailers. Administrators create routes from active route templates, which establish route types for different markets and can reference tour and visit templates. Route validity dates determine when a route can be used, and the route, warehouses, vehicles, and related templates must use compatible sales organizations.","Customers are added to a route as route-account associations and are assigned sequence values that determine the order in which the driver serves them. The sequence can be changed directly or by using drag-and-drop controls, and each sequence value must be unique and greater than zero. When a tour is created from a route, Consumer Goods Cloud creates a corresponding visit for each customer and uses the route sequence to organize those visits. Map visualization can support route and visit planning when valid store coordinates are maintained."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.cg_task_admin_add_customers_route.htm&type=5&language=en_US",connections:[{"planet":"accounts_stores","desc":"Routes contain ordered sequences of customer stops"},{"planet":"maps_territory","desc":"Route optimization uses map-based distance calculations"}]},
    {id:"tours",name:"Tours & Tour Execution",icon:"\u{1F4CD}",desc:"Tours & Tour Execution manages executable trips with assigned users, vehicles, warehouses, visits, checks, and supported documents. A tour can be created from a route or independently from a tour template, and its duration can be more than one day. Tour execution covers start-of-tour activities, customer visits, deliveries or van sales, and end-of-tour activities in the Consumer Goods Cloud offline mobile app.",tags:["cgcloud__Tour__c","cgcloud__Tour_Template__c","cgcloud__Tour_Check__c","cgcloud__Tour_Template_Tour_Check__c","cgcloud__Tour_Template_Object_Reference__c"],docs:["Tour templates define tour settings, vehicle and safety checks, start- and end-of-tour guidance, object references, and signature flows. A tour created from a route inherits warehouse, user, vehicle, customer, and visit details, while an independent tour is created directly from a tour template. Template settings are copied to the tour, and execution uses the settings stored on the tour rather than continuing to read them from the template.","At the start of a tour, the driver can review assignments, perform vehicle and safety checks, record time and GPS information, and check products out from the warehouse. During customer visits, the driver can deliver products, create van sales or pre-sales orders when allowed, collect payments, process returns or empties, and capture required signatures. These activities are accessed through documented mobile experiences such as the Delivery Cockpit, driver cockpit, and Your Day; Consumer Goods Cloud does not identify this interface as a tour cockpit.","At the end of the tour, the driver can review vehicle details, check products and cash in, record inventory or cash differences, perform audits, and complete configured end-of-tour checks. Tour status transitions enforce the completion of applicable start- or end-of-tour checks, and completed or canceled tours have editing restrictions. Tour and related visit or order data are synchronized with Salesforce according to the configured sync options."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.cg_concept_admin_tour_planning.htm&type=5&language=en_US",connections:[{"planet":"visit_execution","desc":"Tours contain ordered visits that are executed sequentially"},{"planet":"mobile_app","desc":"Tour cockpit and driver cockpit are on the mobile app"}]},
    {id:"warehouses",name:"Warehouses",icon:"\u{1F3ED}",desc:"Warehouses represent manufacturer depots from which drivers begin and end delivery or van sales tours in Consumer Goods Cloud. Warehouse records store location, address, communication, sales organization, product, user, and vehicle information. Product, driver, and vehicle assignments determine what can be used for warehouse-based sales and delivery processes.",tags:["cgcloud__Warehouse__c","cgcloud__Warehouse_Product__c","cgcloud__Warehouse_User__c","cgcloud__Vehicle_Warehouse__c"],docs:["A warehouse record identifies the depot and can include its business unit, sales organization, Global Location Number, address, geographic coordinates, phone numbers, and email address. Warehouses serve as tour start and end points, and route and tour validation requires compatible warehouse, vehicle, driver, and sales organization assignments. Accurate warehouse coordinates also support configured geofencing checks at the beginning and end of tours.","Products assigned to a warehouse are available for direct store delivery and van sales processes, and drivers' devices show products from their assigned warehouses. Users must be assigned to a warehouse before they can take products out of it. Vehicles are associated with warehouses so Consumer Goods Cloud can track which trucks and trailers carry goods from each depot."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.cg_concept_admin_warehouse_management.htm&type=5&language=en_US",connections:[{"planet":"products_assortments","desc":"Warehouses stock products from the product catalog"},{"planet":"accounts_stores","desc":"Warehouses belong to sales organizations"}]},
    {id:"vehicles",name:"Vehicles",icon:"\u{1F69B}",desc:"Vehicles records identify the trucks, trailers, and other vehicles used to carry goods from warehouses to stores or other locations. Consumer Goods Cloud supports vehicle types used in route and tour assignments and associates vehicles with warehouses. Vehicle details and configured checks support operational and safety reviews during tour execution.",tags:["cgcloud__Vehicle__c","cgcloud__Vehicle_Warehouse__c"],docs:["Administrators create vehicle records with a name, description, vehicle type, license plate or registration number, and sales organization. Documented vehicle types include Car Standard, Truck Slow, Truck Fast, and Trailer. Routes and tours can reference a truck and trailers, subject to validation against the vehicle type and the warehouses assigned to the vehicle.","Tour templates can require drivers to review vehicle status, complete vehicle and safety checks, and record odometer readings or photos. Tour checks can be configured for the start of the day, the end of the day, or both, and their sort values determine the execution order. Depending on the configuration, incomplete checks can prevent the driver from beginning visits or completing the tour."],connections:[{"planet":"mobile_app","desc":"Vehicle identification and inspection happens on mobile"}]},
    {id:"inventory-management",name:"Inventory & Transactions",icon:"\u{1F4E5}",desc:"Inventory & Transactions tracks product stock, customer quotas, and cash floats in Consumer Goods Cloud. Inventory can be assigned to tours, vehicles, users, accounts, or supported combinations, while inventory transactions record every change to quantity or value. Templates define inventory properties and transaction behavior so mobile and distributed inventory can be tracked consistently.",tags:["cgcloud__Inventory__c","cgcloud__Inventory_Transaction__c","cgcloud__Inventory_Control_Template__c","cgcloud__Inventory_Transaction_Template__c","ProductTransfer","ProductItem","Shipment"],docs:["Inventory control templates define whether a record represents inventory, quota, or cash float and specify its control measure, period, and applicable product, customer, user, vehicle, or tour policies. Inventory records can therefore track products handled by reps, limits on products supplied to customers or users, and cash collected during order processes. Order item and order payment configurations associate these templates with the applicable business documents.","Inventory transaction templates define transaction control and transaction types such as addition, withdrawal, balance, or void. Product check-out creates addition transactions for goods loaded onto a vehicle, while deliveries and van sales can create withdrawal transactions for goods removed from that inventory. Returns create positive addition entries, and each inventory-changing trigger is represented by an inventory transaction for auditability.","The InventoryTxBalanceCalculationBatch reconciles unaccounted additions and withdrawals and writes the result to a balanced transaction for the inventory. The balance represents the sum of applicable addition and withdrawal transactions, while transactions configured as Neutral are excluded from reconciliation. Inventory deviation insights can identify differences between expected and actual quantities and products present on a truck but absent from a check-in document."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.cg_concept_admin_inventory_management.htm&type=5&language=en_US",connections:[{"planet":"visit_execution","desc":"Inventory changes when orders are placed and delivered"},{"planet":"mobile_app","desc":"Inventory check-out and check-in happens on mobile"}]},
    {id:"order-payments",name:"Order Payments & Invoicing",icon:"\u{1F4B3}",desc:"Order Payments & Invoicing supports payment collection and document generation for orders, deliveries, and van sales in Consumer Goods Cloud. Order payment templates define supported payment methods and are assigned to order templates, while order payment records store payment amounts and payment type. Document Transaction Types determine whether payment collection is required and which order or invoice document is produced.",tags:["cgcloud__Order_Payment__c","cgcloud__Order_Payment_Template__c","cgcloud__Order_Payment_Inventory_Transaction__c","cgcloud__Order_Template_Order_Payment_Template__c","DeliveryTask"],docs:["An order payment template defines a payment method such as check, cash, deduction, credit card, money order, debit card, expense, or multiple payments. It can also specify whether details such as effective date, expiration date, bank code, account number, holder name, Card Security Code, or item number are optional or required. The Order Template Order Payment Template association assigns an order payment template to the applicable order template.","Order payment records store payment information for an order, including gross and net amounts and the payment type. Payment information is displayed for supported document transaction types, and payment collection can occur during delivery or van sales execution. Cash float inventory transactions track qualifying cash or check payments according to the inventory references and templates configured for the order payment process.","The Order Payment Inventory Transaction object is documented as an association between an order payment template, inventory template, and inventory transaction template. It configures how a payment affects the applicable cash-float inventory; it does not directly link an individual payment to a physical product movement. DSD delivery documents are handled as order documents, while Delivery Task records are associated with shipments to define products that must be delivered during a visit."],connections:[{"planet":"visit_execution","desc":"Order payments are processed during visit finalization"},{"planet":"accounts_stores","desc":"Payment terms are defined per customer relationship"}]}
  ],
  dataFlow: ["Assign products, users, and vehicles to warehouses, and use product velocity insights to inform vehicle loading.","Create route and tour templates, then sequence customer accounts on routes with map visualization and applicable visit templates.","Create a tour from a route or independently, and feed its schedule and ordered stops into visit planning.","Sync the tour, visits, documents, and inventory data to the Consumer Goods Cloud offline mobile app, then complete checks and product check-out.","Execute customer visits, use applicable assortments for orders, deliver products, collect payments, and record inventory transactions.","Complete end-of-tour checks, product and cash check-in, inventory reconciliation, document generation, and synchronization back to Salesforce."],
  connections: [{"planet":"visit_execution","desc":"Van sales orders and deliveries happen during visits"},{"planet":"products_assortments","desc":"Warehouses stock products; orders use assortments"},{"planet":"accounts_stores","desc":"Routes serve ordered sequences of customer accounts"},{"planet":"mobile_app","desc":"DSD operations run on the offline mobile app"},{"planet":"maps_territory","desc":"Route planning benefits from map visualization"},{"planet":"visit_planning","desc":"Tour schedules and route stops feed visit planning"},{"planet":"einstein_ai","desc":"Product velocity insights inform van sales loading"}]
},

mobile_app: {
  packages: ["consumergoods"],
  name: "Mobile & Sync",
  icon: "\u{1F4F1}",
  color: "#22d3ee",
  description: "Mobile & Sync covers the Consumer Goods Cloud offline mobile app, its synchronization infrastructure, mobile customization, and access to Agentforce from mobile devices. The mobile app is the primary field platform for visit execution, offline visit planning, ad hoc visit creation, Direct Store Delivery and van sales, surveys, orders, asset checks, and customer master updates. Sync Management distributes customer master data, product catalogs, assortments, sales folders, visits, process data, metadata, and Runtime Artifacts between Salesforce and mobile devices by using tracked objects, named queries, and named fetch trees. VS Code Based Modeler supports design-contract customization, while Agentforce provides online agent interactions through the Consumer Goods Cloud mobile app interface.",
  components: [
    {id:"offline-mobile-app",name:"CG Offline Mobile App",icon:"\u{1F4F2}",desc:"The CG Offline Mobile App is the primary Consumer Goods Cloud platform for planning and executing field visits when network access is unavailable. It supports advanced visit execution, store audits, product surveys, asset checks, customer tasks, order taking, and editable customer master data in the enhanced data model. Direct Store Delivery and van sales activities also run on mobile devices, including tour activities, deliveries, inventory handling, payments, and returns. Some capabilities, including Agentforce, remote calls, and map services, require the device to be online.",tags:["Visit","cgcloud__Order__c","cgcloud__Visit_Job__c"],docs:["Field reps use the Consumer Goods Cloud offline mobile app to record data while executing visits, even when they’re offline. The enhanced data model supports offline visit planning, ad hoc visit creation, advanced orders, Penny Perfect Pricing, sales folders, inventory management, surveys, and asset management. Visit Execution, Store Audit, Product Survey, Asset Check, Customer Tasks, and Order Taking for field users are supported in this app rather than in the Salesforce mobile app. The new UI flow also lets users view and edit customer master data and adjust personal settings.","Consumer Goods Cloud synchronizes customer master data, products, product assortments, sales folders, visits, orders, and other process data required by field users. For ad hoc visits or orders, users can create the record while online to download the related customer data and then execute the work fully offline. Historical data should be limited to what field reps need, and the documented synchronization guidelines recommend the First Sync of the Day before the first visit and another synchronization before closing the day. Only necessary attachments should be synchronized in advance, while other supported attachments can be downloaded on demand in online mode and accessed later offline.","Direct Store Delivery and van sales use tours, routes, warehouses, vehicles, inventories, orders, payments, and visits on the Consumer Goods Cloud offline mobile app. Drivers can perform start-of-day vehicle and safety checks, inventory check-out, delivery or van sales execution, cash collection, returns, signatures, and end-of-day inventory check-in. The app can create inventory transactions as products are loaded, delivered, returned, or reconciled. Tour and related account, visit, order, and inventory data must be included in the applicable synchronization configuration and shared with the assigned users."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.cg_concept_admin_setup_cg_offline_app.htm&type=5&language=en_US",connections:[{"planet":"visit_execution","desc":"All visit execution happens through the mobile app"},{"planet":"van_sales","desc":"DSD tour operations run on mobile with driver and tour cockpits"}]},
    {id:"sync-management",name:"Sync Management",icon:"\u{1F504}",desc:"Sync Management configures and monitors synchronization between Salesforce and the Consumer Goods Cloud offline mobile app. During synchronization, it checks for changes to business and workflow data, Runtime Artifacts, and metadata in Salesforce and transfers applicable updates to mobile devices. Its configuration uses tracked objects, named queries, and named fetch trees to determine the data available to each mobile user. Sync Management also distributes mobile deployment packages and provides device status and logging controls.",tags:["Sync_Config__c","Sync_Tracked_Object_Config__c"],docs:["The Consumer Goods Cloud Mobile Sync managed package provides the synchronization capabilities between Salesforce and mobile devices. Administrators use the Sync Management app to configure how data is synchronized, while users require the Consumer Goods Cloud Mobile Sync User permission set to synchronize data on their devices. Synchronization configurations can be assigned to users, roles, or profiles, including configurations for retail execution, Direct Store Delivery, hybrid users, and route sales users. The configured dataset should include only the records and fields required for the user’s mobile processes.","Synchronization should provide foundational data independently of planned visits and visit-dependent data for the period needed in the field. Foundational data includes product master data, key customer master data, user settings, and business templates; visit synchronization can include customer details, activities, prices, promotions, assortments, and sales folders. Consumer Goods Cloud recommends daily First Sync of the Day synchronization, timer-based or event-based synchronization during the day, and synchronization before the user closes the day. Distribution reorganization settings and CallOrderDistributionReOrgBatch can limit historical visits and orders marked as relevant for mobile distribution.","Sync Management also supports deployment and device administration. Administrators upload deployment packages on the Deployment Packages page, then assign and publish them to all users or selected users or groups. Device Status Overview supports remote requests such as turning on the debug window, and mobile logs can help diagnose synchronization, deep-link, or Bluetooth scanner issues. When completing a Consumer Goods Cloud release upgrade, users must download the latest version of the Consumer Goods Cloud mobile app from the Apple App Store or Google Play Store to apply the changes in the deployment package."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.se_concept_sync_intro.htm&type=5&language=en_US",connections:[{"planet":"accounts_stores","desc":"Customer master data is synced to devices"},{"planet":"products_assortments","desc":"Product and assortment data syncs to mobile"}]},
    {id:"tracked-objects",name:"Tracked Objects",icon:"\u{1F4BE}",desc:"Tracked Objects define which Salesforce objects participate in synchronization with the Consumer Goods Cloud offline mobile app. Their configuration can include filtering conditions that restrict synchronized records to the relevant sales organization, hierarchy, user, date range, or business process. Mobile-relevant field sets further limit each object to fields required by mobile functionality. Together with distribution reorganization settings and named queries, tracked objects control the records shown on offline devices.",tags:["Sync_Tracked_Object_Config__c"],docs:["Administrators configure tracked objects from Sync Configuration in the Sync Management app. A tracked object configuration identifies the object and can apply a where condition that references user data or the results of named queries. For example, the documented Complex Pricing Condition configuration filters valid conditions and uses RelevantHierarchyAccountsForUser and SalesOrganizationId results. Administrators can execute a configuration to verify its behavior before saving it.","For each synchronized object, define a MobilityRelevant field set containing only the fields that the Consumer Goods Cloud mobile app requires. Excluding reporting fields, fields used only by unsupported apps, and complex address fields reduces synchronization work, device storage, and processing demand. The Consumer Goods Cloud offline mobile app doesn’t support complex address fields such as shippingAddress and billingAddress, so use the component fields from Address Compound Fields and omit the complex fields from mobile-relevant field sets. Field permissions and record sharing must also allow the user to access the synchronized data.","Tracked object configurations vary by operational persona and process. Direct Store Delivery, hybrid, and route sales synchronization configurations include their own tracked object records so that tours, visits, orders, inventories, and related customer data are available to the appropriate users. Supervisor-specific rules should synchronize essential account and visit information without automatically downloading all dependent pricing, assortment, and historical data. Static resource updates can add, modify, or delete tracked object configurations as Consumer Goods Cloud synchronization requirements change between releases."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.se_task_sync_map.htm&type=5&language=en_US",connections:[{"planet":"visit_execution","desc":"Visit and order data tracked for offline access"}]},
    {id:"named-queries-fetch-trees",name:"Named Queries & Fetch Trees",icon:"\u{1F333}",desc:"Named Queries & Fetch Trees are Sync Management mechanisms used to select and retrieve related data for the Consumer Goods Cloud offline mobile app. Named queries expose reusable query results that tracked object conditions can reference by bindable name. Named fetch trees retrieve connected records required for a mobile process, including Direct Store Delivery tour data. They are included in synchronization configurations assigned to mobile users and personas.",tags:["Sync_Named_Fetch_Tree_Nodes__c"],docs:["A named query consists of a bindable name and a SOQL statement. Other synchronization rules can reference the named result by using its bindable name, enabling a tracked object filter to reuse contextual data. For example, the documented SalesOrganizationId named query selects the Sales Organization whose name matches the current user’s Mobility Sales Org. Administrators create and test named queries from Sync Configuration in the Sync Management app.","Named fetch trees support retrieval of related records as a connected set. Direct Store Delivery uses named fetch trees when a driver accesses a tour whose data wasn’t synchronized because the tour falls outside the configured synchronization period. If the driver confirms the request, Consumer Goods Cloud synchronizes the tour data using the DSD Named Fetch Trees. Named fetch tree nodes are also delivered and updated through synchronization static resource data.","Synchronization profiles combine named queries, named fetch trees, and tracked objects for specific operating models. The hybrid synchronization configuration uses these mechanisms to synchronize both retail execution and Direct Store Delivery data, while the route sales configuration synchronizes accounts and related data for assigned tours. Administrators should keep these configurations aligned with the data and processes that each mobile persona needs. Updates supplied through static resources must be applied in release order when upgrading managed packages."],connections:[{"planet":"accounts_stores","desc":"NFTs fetch complete store information in one request"}]},
    {id:"vs-code-modeler",name:"VS Code Based Modeler",icon:"\u{1F527}",desc:"VS Code Based Modeler is the Consumer Goods Cloud development environment for configuring and customizing the mobile app on Windows or Mac. It models design contracts, which are XML files defining the mobile user interface, processes, objects, data sources, labels, and other model elements. Customizers can extend the mobile data model and business logic, introduce UI elements, create themes, translate labels, and customize cockpits. The integrated Modeler CLI validates, builds, simulates, and packages mobile customizations.",tags:[],docs:["Visual Studio Code Based Modeler uses design contracts and business logic contracts to customize the Consumer Goods Cloud mobile app. Supported customization areas include mobile data model extensions, data validation, UI elements, mobile themes, translated labels and messages, and cockpit design. Visual Studio Code serves as the editor, while the Modeler CLI plugin is integrated with Salesforce CLI. The simulator app can be used to review the modeled mobile experience before deployment.","The Modeler CLI supports validating contracts, building the customized app, running a local simulation, and creating deployment packages. From a Modeler workspace, run the documented Modeler commands to build the contracts and generate the deployment package. Administrators then import the package on the Deployment Packages page in Sync Management and assign it to the intended Consumer Goods Cloud mobile app users. Users complete synchronization so that deployed contract customizations take effect on their devices.","Modeler, design contracts, managed packages, and the Consumer Goods Cloud mobile app are separate parts of a complete release upgrade. Design contract changes must be applied manually and aren’t automatically upgraded, and Salesforce recommends using the latest Modeler version to avoid errors. In the documented upgrade sequence, administrators update the Modeler CLI plugin, upload and publish the deployment package, and users download the latest Consumer Goods Cloud mobile app from the Apple App Store or Google Play Store to apply the package changes. The upgraded experience should be tested on handheld devices before deployment to production."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.cg_modeler_parent.htm&type=5&language=en_US",connections:[{"planet":"visit_execution","desc":"Modeler customizes visit execution screens and workflows"}]},
    {id:"agentforce-mobile",name:"Agentforce for Mobile",icon:"\u{1F916}",desc:"Agentforce for Mobile makes platform and custom agents available through the Consumer Goods Cloud mobile app interface. Sales reps can use agents to obtain account, visit, order, product, compliance, and upsell insights while working in the app. Agentforce requires a physical mobile device in online mode and supports the Agentforce Employee Agent type. On tablets, users can interact with agents in a collapsible sidebar while continuing their Consumer Goods Cloud workflow.",tags:[],docs:["Administrators enable Agentforce in Consumer Goods Cloud and assign the required Agentforce and Retail Execution permissions to users. In Sync Settings, the Integrate Agentforce in CG mobile app setting enables the Agentforce icon for all users or selected users, while the Agentforce Sidebar setting enables the tablet sidebar. Agentforce in the mobile app works only with the default connected app Consumer Goods Cloud Offline Mobile App. It doesn’t run in the Modeler simulator app and is disabled when the device is offline.","The sidebar preserves chat history as users move through the Consumer Goods Cloud mobile app, and it can use page context for records such as accounts, visits, and orders. Customizers configure context passing in Visual Studio Code Based Modeler by adding process and business logic contracts that construct a payload and call Facade.launchAgentForce(). The payload can identify the Salesforce object, record ID, and optional additional attributes. Context behavior and supported navigation differ by mobile platform, so customizations must be tested on physical devices.","Agents can provide account performance and compliance summaries, visit summaries, product recommendations, and other contextual insights. Records that an agent creates in Salesforce or the Consumer Goods Cloud desktop app aren’t automatically available in the mobile app; users must synchronize the data manually. Agentforce stores a limited amount of chat context per session, and users can clear chat history or restart the app if a long session causes an error. Localization of the Agentforce page and dynamic language switching aren’t supported."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.retail_enable_agentforce_cg_mobile_app.htm&language=en_US",connections:[{"planet":"visit_planning","desc":"Agents suggest visits and provide visit insights"},{"planet":"visit_execution","desc":"Agents recommend products and promotions during visits"}]}
  ],
  dataFlow: ["Configure tracked objects, mobile-relevant fields, named queries, and named fetch trees for each mobile persona.","Build mobile design contracts, package them with VS Code Based Modeler, and publish the deployment package through Sync Management.","Synchronize customer master data, product catalogs, assortments, sales folders, visits, and business templates to each device.","Plan offline visits or create ad hoc visits and orders online to download the required customer data.","Execute visits, surveys, orders, asset checks, Direct Store Delivery, and van sales activities on the Consumer Goods Cloud mobile app.","Synchronize field results back to Salesforce and use Agentforce from the mobile interface while the device is online."],
  connections: [{"planet":"visit_execution","desc":"Mobile app is the primary platform for visit execution"},{"planet":"van_sales","desc":"DSD and van sales operations run on mobile devices"},{"planet":"visit_planning","desc":"Offline visit planning and ad-hoc visit creation on mobile"},{"planet":"accounts_stores","desc":"Customer master data syncs to and from mobile devices"},{"planet":"products_assortments","desc":"Product catalogs and sales folders sync to mobile devices"},{"planet":"agentforce","desc":"Agents are accessible through the mobile app interface"}]
},

maps_territory: {
  packages: ["consumergoods"],
  name: "Maps & Territory",
  icon: "\u{1F5FA}",
  color: "#4ade80",
  description: "Consumer Goods Cloud integrates mapped store and account locations with territory visualization, map-based visit planning, and route optimization. Salesforce Maps provides the Nearby Map component for sales managers, while the enhanced model includes the separate Create Map-Based Visits workflow for the offline mobile app. Route, Tour, and Warehouse records support field routes and van-sales delivery tours. Visit GPS and compliance data can feed territory map overlays for monitoring field execution.",
  components: [
    {id:"salesforce-maps",name:"Salesforce Maps Integration",icon:"\u{1F30D}",desc:"Salesforce Maps Integration connects Consumer Goods Cloud retail execution with map-based territory visualization and visit planning. Administrators can configure Salesforce Maps to display retail stores on record pages, while enhanced-model mapping supports efficient visit planning and route optimization. Google Maps integration for the Consumer Goods Cloud offline mobile app is configured separately from the Salesforce Maps Nearby Map component.",tags:["RetailStore","Account","Location"],docs:["Salesforce Maps helps sales managers visualize and track retail stores in their territories. For example, an administrator can configure a layer that displays retail stores and place the resulting map on a Promotion record page. Sales managers can then view the retail stores running the promotion in a map-based interface. Stores require valid geographical coordinates to appear in embedded maps.","For the enhanced data model, Consumer Goods Cloud provides advanced mapping capabilities for visit planning and route optimization. Creating visits from core maps schedules or maps advanced visit plans requires a custom output object for Visit, custom settings for default values, and a record-triggered flow that assigns the default visit template and Place ID. Google Maps is a separate integration in the Consumer Goods Cloud offline mobile app and uses the Maps JavaScript API and Directions API."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.retail_concept_admin_setup_sfmaps.htm&type=5&language=en_US",connections:[{"planet":"accounts_stores","desc":"Stores and accounts are plotted on maps by location"},{"planet":"visit_planning","desc":"Maps provide territory context for visit planning decisions"}]},
    {id:"nearby-map",name:"Nearby Map Component",icon:"\u{1F4CD}",desc:"The Nearby Map Component is a Salesforce Maps component for helping sales managers visualize and track their territories. Administrators select the object to display and configure an appropriate map layer. For example, sales managers can view the retail stores running a promotion when the component is placed on the Promotion record page.",tags:["RetailStore","Location"],docs:["Create a Nearby Map component from the Salesforce Maps package configuration under Nearby Maps. Provide a name and layer label, and select the object that the map displays. The resulting component gives sales managers a map-based view of the configured business records.","Add the component to an appropriate Lightning record page by using Lightning App Builder. From Custom - Managed, place Maps Nearby Maps on the page and select the configured layer in the Nearby Map field. Save and activate the page to make the visualization available to sales managers. Nearby Map is distinct from the Create Map-Based Visits workflow in the Consumer Goods Cloud offline mobile app."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.cg_task_user_create_map_based_visits.htm&type=5&language=en_US",connections:[{"planet":"visit_planning","desc":"Nearby stores can be selected for ad-hoc visit creation"},{"planet":"mobile_app","desc":"Nearby map works with mobile GPS for location awareness"}]},
    {id:"route-optimization",name:"Route Optimization",icon:"\u{1F6A9}",desc:"Route Optimization uses the advanced mapping capabilities of Consumer Goods Cloud to support efficient visit planning and optimized routes for field reps. Route and tour management uses the Route, Tour, and Warehouse objects to organize customer stops and executable trips. The same route and tour structure supports van sales and delivery operations.",tags:["Visit","RetailStore","OperatingHours"],docs:["Consumer Goods Cloud retail execution helps sales managers plan visits for the right stores at the right time and provide optimized routes to field reps. In the enhanced model, advanced maps support efficient visit planning and route optimization. The documentation does not prescribe an optimization algorithm or state that the feature uses Visit, RetailStore, and OperatingHours as its route-management objects.","For route and tour management, create route templates and tour templates, assign warehouses, users, vehicles, and customers to routes, and create independent tours or tours from routes. A Route defines key characteristics for delivery, sales, or merchandising trips and can contain customer stops in a specific sequence with a visit type. Route Customer is the association between Route and Account. A Tour represents an executable trip and can be created from a route as a van-sales tour or created independently."],connections:[{"planet":"van_sales","desc":"DSD route sequences can be optimized for delivery efficiency"},{"planet":"visit_planning","desc":"Optimized routes feed into trip list creation"}]},
    {id:"map-based-visits",name:"Map-Based Visit Creation",icon:"\u{1F4CC}",desc:"Map-Based Visit Creation is an enhanced-model workflow in the Consumer Goods Cloud offline mobile app. It supports planning visits from mapped customer locations and is listed separately from the Nearby Map component. Enhanced-model offline actions also include ad-hoc visit creation based on territories.",tags:["Visit","RetailStore"],docs:["Create Map-Based Visits is one of the visit-planning workflows available in the Consumer Goods Cloud offline mobile app for the enhanced model. Accurate coordinates must be maintained for store locations so that stores can be viewed effectively on the map. Map-based visit planning in the offline mobile app can show up to 105 customers.","To create visits from core maps schedules or maps advanced visit plans, configure Visit as a custom output object for Salesforce Maps. Create a lookup relationship from Visit to Maps Advanced Route Waypoint, configure Visit under Routes & Schedule, and disable Event to prevent overlapping entries because scheduling a visit also creates an event. Configure Visit Defaults for Maps and a record-triggered flow to assign the default Visit Template, Place ID, and record type before visit creation."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.cg_task_user_create_map_based_visits.htm&type=5&language=en_US",connections:[{"planet":"visit_planning","desc":"Map selections drive visit creation"},{"planet":"accounts_stores","desc":"Map shows store details and visit history"}]},
    {id:"territory-visualization",name:"Territory Visualization",icon:"\u{1F3D9}",desc:"Territory Visualization combines mapped store locations with the territory structures maintained in Consumer Goods Cloud. Org Units can represent physical territories for sales teams, while Sales Organizations can segment business data by geographical territory. Salesforce Maps layers and visit GPS and compliance data support territory-level views of stores and field execution.",tags:["cgcloud__Org_Unit__c","cgcloud__Sales_Organization__c","RetailStore"],docs:["Consumer Goods Cloud supports territory structures through Org Units, Org Unit Hierarchies, and Sales Organizations. Org Units can be based on physical territories for sales teams, and their hierarchies represent relationships between organizational units. Sales Organizations can structure data and business processes using geographical territories, product divisions, or account teams.","Salesforce Maps can display retail stores through a configured Nearby Map layer so that sales managers can visualize and track their territories. Valid geographical coordinates must be maintained for stores to appear on embedded maps. Visit GPS and compliance data can feed territory map overlays, linking visit execution results with the mapped stores and territories that managers monitor."],connections:[{"planet":"accounts_stores","desc":"Org units and sales orgs define territory boundaries"},{"planet":"visit_execution","desc":"Visit compliance and KPI data overlays on territory maps"}]}
  ],
  dataFlow: ["Maintain store coordinates and territory structures for mapped accounts and retail locations.","Configure Salesforce Maps layers, record pages, and enhanced-map visit output settings.","Visualize territory stores and promotion participation with the Nearby Map component.","Plan Create Map-Based Visits and optimize routes separately from Nearby Map visualization.","Build delivery and van-sales tours with Route, Tour, Warehouse, and sequenced customer assignments.","Feed visit GPS and compliance data into territory map overlays."],
  connections: [{"planet":"visit_planning","desc":"Map-based visit creation and route optimization"},{"planet":"accounts_stores","desc":"Store locations and territories displayed on maps"},{"planet":"van_sales","desc":"Route planning for delivery tours"},{"planet":"visit_execution","desc":"Visit GPS and compliance data feed territory map overlays"}]
},

tpm_master_data: {
  packages: ["consumergoods"],
  name: "TPM Master Data",
  icon: "\u{1F4C1}",
  color: "#fbbf24",
  description: "TPM Master Data is the foundation for consistent customer, product, sales-organization, user, segmentation, and distribution information in Consumer Goods Cloud. It collects, organizes, and distributes data used by promotions, funds and budgets, claims, and account planning. Customer and product records supply the planning dimensions for promotions and fund allocation, while customer roles and relationships identify claim and payment parties. Time-dependent account hierarchies also structure account-plan P&L views and provide the account hierarchy shared with Retail Execution.",
  components: [
    {id:"tpm-customer-master",name:"Customer Master",icon:"\u{1F465}",desc:"Customer Master centralizes the account information that Consumer Goods Cloud uses across trade promotion and retail processes. It represents customers, time-dependent trade organization hierarchies, account roles, account relationships, receivables, contacts, and assigned users. These structures identify promotion customers, claim recipients and payment relationships, fund and budget anchors, account-planning rollups, and the account hierarchies shared with Retail Execution.",tags:["Account","cgcloud__Account_Extension__c","cgcloud__Account_Relationship__c","cgcloud__Account_Template__c","cgcloud__Account_Trade_Org_Hierarchy__c","cgcloud__Sub_Account__c"],docs:["The Account object stores information about customers with whom the organization conducts business, including retailers, distributors, wholesalers, and consumers. Customer Extension holds additional information such as account classification, status, pricing configuration, and account roles used in visits and promotions. Account Receivable provides customer information about invoices, debit notes, and credit notes. Contact records identify primary contacts, such as store managers or buyers, and other contacts associated with an account.","Trade Org Hierarchy represents time-dependent parent-child relationships among accounts. It enables retail activities to be planned at a parent level and inherited by child accounts, while Sub-Account supports account-planning scenarios in which child KPIs contribute to parent account KPIs. These account hierarchies also provide the customer structure shared with Retail Execution. Customer Org Unit relates customers to org units, with the requirement that both records belong to the same sales org.","Customer Relationship specifies operational relationships such as Bill To, Delivery Recipient, Payee, Payer, and Wholesaler. A customer can have multiple relationships of the same type but only one primary relationship for each type. These relationships determine which account is billed, receives delivery, or participates in payment processing. They therefore provide the customer and payment-party context used when handling claims and related financial processes."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.cg_task_admin_create_customer.htm&type=5&language=en_US",connections:[{"planet":"promotions","desc":"Customer records anchor promotions"},{"planet":"account_planning","desc":"Accounts drive business plans and P&L views"}]},
    {id:"tpm-product-master",name:"Product Master",icon:"\u{1F4E6}",desc:"Product Master stores the information required to identify and organize products in Consumer Goods Cloud. It covers products and product groups, time-dependent hierarchies, product parts, units of measure, product conditions, managers, and warehouses. Products and their hierarchy positions provide the catalog used for promotion planning and the product dimensions that anchor fund allocation and reporting.",tags:["Product2","cgcloud__Product_Hierarchy__c","cgcloud__Product_Part__c","cgcloud__Product_Template__c","cgcloud__Product_Condition__c","cgcloud__Product_Category_Share__c"],docs:["Product2 stores product details and related information, including product parts, product conditions, units of measure, product managers, and warehouses. A product record can represent a sellable product or a product group, with Product Template defining the shared characteristics and sales org for products created from the template. Product master data is typically interfaced from an ERP system, while users can maintain additional information such as attachments and competitor products in Consumer Goods Cloud.","Product Hierarchy represents how a manufacturer organizes products and supports parent-child relationships between product groups or between product groups and products. Consumer Goods Cloud supports a dynamic hierarchy through parent relationships and a static hierarchy for optimized access in processes such as Condition Search in Penny Perfect Pricing. Units of measure define logistical units and support quantity calculation during order taking. Product Part records describe how child products combine under a parent product, while Product Manager identifies an active manager who can plan promotions."],docUrl:"https://help.salesforce.com/s/articleView?language=en_US&id=sf.tpm_concept_admin_product_management.htm&type=5",connections:[{"planet":"promotions","desc":"Products are resolved into promotion tactics"},{"planet":"products_assortments","desc":"Products feed into store assortment lists"}]},
    {id:"tpm-sales-organizations",name:"Sales Organizations",icon:"\u{1F3E2}",desc:"Sales Organizations create business segments within Consumer Goods Cloud for structuring data, configurations, and business processes. Segmentation can reflect geographic territories, product divisions, or account teams, and master data is unique to each sales org. Sales organizations support multi-market operation for enhanced-model processes such as advanced visits, advanced orders, sales folders, and advanced promotions.",tags:["cgcloud__Sales_Organization__c"],docs:["Sales Organization records define the business segments used to separate data and processes within one Salesforce org. Consumer Goods Cloud can use a global-template approach while maintaining different products, accounts, configurations, and go-to-market processes for each market. Multi-market management supports enhanced-model processes out of the box, but it doesn’t provide out-of-the-box multi-market support for retail stores, assessment tasks, action plans, or retail store KPIs.","Sales Organization User associates a user with a sales org and enables that user to access its data and work on activities, visits, or orders. A user can be assigned to multiple sales orgs but actively works in one default sales org session at a time. A Mobility Sales Org determines which sales org data is synchronized to the Consumer Goods Cloud offline mobile app, and a user can belong to only one Mobility Sales Org. Consumer Goods Cloud supports a maximum of 30 sales orgs in one Salesforce org."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.tpm_sales_org_parent.htm&type=5&language=en_US",connections:[{"planet":"promotions","desc":"Sales org scopes promotion templates"},{"planet":"funds_budgets","desc":"Sales org scopes fund templates"}]},
    {id:"tpm-user-management",name:"User & Substitution",icon:"\u{1F464}",desc:"User & Substitution manages business roles, customer responsibility, account access, and temporary coverage for unavailable representatives. Users operate within sales organizations and can be assigned to accounts directly or through org units. Substitution records preserve customer operations for defined periods when the primary representative is absent.",tags:["User","cgcloud__User_Setting__c","cgcloud__User_View__c"],docs:["User records represent business roles within a sales org, such as sales rep or supervisor, while Sales Organization User maps users to the sales organizations in which they work. Customer Manager assigns users to accounts directly or through the AccountManagerOrgUnitBased batch process. EffectiveAccountManagerSyncBatch creates account team members from valid customer managers so those managers can access the corresponding accounts. User Setting stores account, visit, calendar, working-day, and KPI subset preferences used to personalize the Consumer Goods Cloud offline mobile app.","Substitution manages planned and unplanned absences of sales reps. A substitute can be assigned to one or multiple customers, and multiple substitutes can be assigned to one customer for specified periods. The same object stores substitution and customer-substitution records and distinguishes them through Record Type. When substitution records are activated, deactivated, or have their time frames changed, the CGCloud : Manager to Customer based on Substitution Flow manages the corresponding account-manager records."],docUrl:"https://help.salesforce.com/s/articleView?language=en_US&id=sf.tpm_manage_users.htm&type=5",connections:[{"planet":"promotions","desc":"Users manage and own promotions"},{"planet":"account_planning","desc":"KAMs own account plans and business plans"}]},
    {id:"tpm-account-sets",name:"Account Sets",icon:"\u{1F4CB}",desc:"Account Sets group customers that perform similar promotion, pricing, or activity processes in Consumer Goods Cloud. A Customer Set can be populated manually, integrated from an external system, or generated through segmentation rules. These groups let planners target and manage work at a group level rather than repeating the same setup for each customer.",tags:["cgcloud__Account_Set__c","cgcloud__Account_Set_Account__c"],docs:["Customer Set stores a group of customers used for common processes such as promotions, pricing, and activities. Customer Set Customer associates an individual account with a Customer Set. Customer Set Manager associates a user with the set and can be used for promotion sharing rules. Activities and advanced promotions can reference Customer Sets to target the included accounts.","Segmentation Rule connects a Segmentation Rule Definition, Segmentation Rule Template, Account, and Customer Set. Segmentation Rule Definition contains the SOQL query and filter criteria used to create the set and specifies whether filtering follows the account hierarchy or org unit hierarchy. Flatten Org Unit Hierarchy provides batch-flattened hierarchy data that can be used to filter and group customers. The customer segmentation process can add up to 100,000 accounts to a Customer Set."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.cg_task_admin_create_customer_sets.htm&type=5&language=en_US",connections:[{"planet":"promotions","desc":"Account sets define promotion customer scope"},{"planet":"data_cloud","desc":"Segmentation rules feed account set creation"}]},
    {id:"distribution-profiles",name:"Distribution Profiles",icon:"\u{1F4C5}",desc:"Distribution Profiles allocate customer product or category values across weekdays or subperiods in Consumer Goods Cloud. Week Day Share Profile can express the allocation as percentages or absolute values and associate it with an account and product hierarchy. Validity dates and daily shares provide a time-bounded pattern for distributing KPIs and delivery-related values.",tags:["cgcloud__Week_Day_Share_Profile__c"],docs:["Week Day Share Profile stores the breakdown of product or category deliveries across days of the week or subperiods. A profile can be defined as either a percentage or an absolute value. Consumer Goods Cloud uses the profile to distribute KPIs across weekdays or subperiods. The weekly profile can be updated when product rates change during a week or when a promotion begins midweek.","The profile identifies the related account and product hierarchy and records separate shares for Monday through Sunday. Valid From and Valid Thru establish the period during which the distribution applies. This structure lets Consumer Goods Cloud retain a customer- and product-specific weekday allocation rather than applying one undifferentiated weekly value."],connections:[{"planet":"analytics","desc":"Distribution profiles feed sub-weekly KPI calculations"}]}
  ],
  dataFlow: ["Define sales organizations to segment markets, master data, users, and business processes.","Load customers, account hierarchies, roles, relationships, receivables, and payment parties.","Load products, product hierarchies, units of measure, conditions, and related catalog data.","Assign users and substitutes, build Account Sets, and maintain weekday distribution profiles.","Use customers and products for promotions, and anchor funds and budgets to the relevant accounts and products.","Apply customer hierarchies to claims, account-planning P&L views, and the account structures shared with Retail Execution."],
  connections: [{"planet":"promotions","desc":"Master data provides customers and products for promotion planning"},{"planet":"funds_budgets","desc":"Accounts and products anchor fund allocation"},{"planet":"claims","desc":"Customer master determines claim recipients and payment relationships"},{"planet":"account_planning","desc":"Account hierarchies structure business plan P&L views"},{"planet":"accounts_stores","desc":"Customer master shares account hierarchies with Retail Execution"}]
},

promotions: {
  packages: ["consumergoods"],
  name: "Promotions",
  icon: "\u{1F3AF}",
  color: "#f87171",
  description: "The Promotions domain in Consumer Goods Cloud manages Sellable Promotions for Retail Execution and supports the separate transfer of eligible Trade Promotion Management promotions into Retail Execution. Promotions use customer and product master data, customer hierarchies, customer sets, and product listings, and a Key Account Manager (KAM)—not a KAM Agent—is the documented persona who manages promotions. Tactics, products, hurdles, rewards, templates, and promotion hierarchies define how promotions are configured, evaluated, extended, and made available for visits and orders; retail reporting provides supported business-performance insights. Agentforce agents can also automate Retail Execution tasks such as generating account and visit insights, suggesting products and promotions, and creating visits, while Data Cloud supports account segmentation, consumer insights, and store-level product performance.",
  components: [
    {id:"advanced-tpm-promotions",name:"Advanced Promotions",icon:"\u{1F4E2}",desc:"Advanced Promotions in Consumer Goods Cloud use Sellable Promotions to support Retail Execution visits and orders. They represent agreements between a manufacturer and a customer intended to increase revenue and market share through methods such as Temporary Price Reductions (TPR) or in-store displays. A Key Account Manager (KAM) manages promotions, while a Business Admin manages the supporting promotion and tactic templates. Trade Promotion Management promotions can also be transferred to Retail Execution as Sellable Promotions when configured as transfer relevant.",tags:["cgcloud__Promotion__c","cgcloud__Promotion_Attachment__c","cgcloud__Promotion_Attachment_Link__c"],docs:["A Sellable Promotion is created from a Promotion Template that determines the promotion type and its behavior. The template can define an anchor type of Customer or Customer Set, creation platform, listing consideration, reward consideration, and whether the promotion is selectable. Before creating a promotion, a user selects the template, dates, anchor customer or customer set, and a slogan. Customer and product master data, customer sets, product hierarchies, and active listings provide the business context for promotion setup.","A Sellable Promotion can contain tactics, tactic products, reward groups, hurdles, expressions, and rewards. Promotion expressions define evaluation criteria, while hurdles compare expression results with configured operators and threshold values. When the relevant hurdles are fulfilled, rewards can provide a Special Base Price, Percentage Discount, Amount Per Unit, Flat Rate, Free Item, or Special reward. Promotion rewards can be considered during Penny Perfect Pricing for promotional orders.","Consumer Goods Cloud prepares promotions for visits and orders through AggregatePromotionBatch. For active, committed Sellable Promotions with a valid date range and an Anchor Customer, the batch finds stores in the anchor account hierarchy and creates promotion store records. Promotions with an Anchor Customer Set directly target the accounts in the set and don’t require the same hierarchical check. Trade Promotion Management promotions use a separate transfer process that recreates eligible promotions as Sellable Promotions in Retail Execution."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.tpm_concept_admin_promotion.htm&type=5&language=en_US",connections:[{"planet":"funds_budgets","desc":"Promotions consume budget from linked funds"},{"planet":"claims","desc":"Executed promotions generate retailer claims"}]},
    {id:"tactics",name:"Tactics",icon:"\u{1F3AD}",desc:"Tactics are the lowest-level actions or procedures performed as steps in a promotion. A Tactic Template creates a tactic and controls promotion behavior for that tactic type. Tactic products identify the promoted products at tactic level and can include quantities and hurdle classification. A Key Account Manager (KAM) can add tactics to promotions, while a Business Admin manages Tactic Templates and their assignment to Promotion Templates.",tags:["cgcloud__Tactic__c","cgcloud__Tactic_Template__c","cgcloud__Tactic_Product__c","cgcloud__Tactic_Product_Condition__c"],docs:["A Tactic Template defines a Tactic Type, sales organization, active status, description, and whether the tactic is order relevant. Documented tactic types include Display, DisplayPerAbs, PriceReduction, and PriceReductionPerAbs. Only Tactic Templates assigned to a Promotion Template can be used to create tactics for promotions created from that template. This template association allows different tactic types to be reused across promotions.","Users add a tactic to a Sellable Promotion by selecting an assigned Tactic Template and specifying the association dates. Products can then be added to the tactic through the Tactic Products related list, and the same product can’t be added twice to one tactic. Tactic products support promotional ordering and can participate in classifications used by promotion hurdles and rewards. The documented promotion flow doesn’t state that tactics consume allocated fund budgets."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.tpm_task_add_a_fund_to_a_tactic.htm&type=5&language=en_US",connections:[{"planet":"funds_budgets","desc":"Tactics are linked to funds that pay for them"},{"planet":"claims","desc":"Claims compensate retailers for executed tactics"}]},
    {id:"trade-calendar",name:"Trade Calendar",icon:"\u{1F5D3}",desc:"Trade Calendar configuration is exposed on Promotion Templates in Consumer Goods Cloud. The documented Trade Calendar section applies only to Trade Promotion Management promotions. It isn’t documented as part of Sellable Promotion setup for Retail Execution. The provided documentation doesn’t describe additional Trade Calendar behavior or configuration.",tags:["cgcloud__User_View__c"],docs:["The Promotion Template separates Trade Promotion Management settings from Retail Execution settings. Its Trade Calendar section is identified as applicable only to Trade Promotion Management promotions, while Retail Execution behavior is configured through settings such as Creation Platform, Selectable Promotion, Consider Listing, Consider Promotion Rewards, and Display In Visit. No further Trade Calendar workflow, fields, or processing rules are specified in the provided documentation."],connections:[{"planet":"account_planning","desc":"Calendar shows account plan timelines alongside promotions"},{"planet":"analytics","desc":"Calendar surfaces KPI data for promotion periods"}]},
    {id:"smart-ui",name:"Smart UI",icon:"\u{26A1}",desc:"Smart UI is a Promotion Template UI Type option in Consumer Goods Cloud. A template can use Standard UI to show the attributes of the selected promotion or Smart UI for Trade Promotion Management promotions. Smart UI isn’t documented as the interface for Sellable Promotions in Retail Execution. Organizations using Trade Promotion Management must use the standard Smart UI before receiving automatic push upgrades.",tags:[],docs:["The UI Type setting on a Promotion Template determines which promotion interface is shown. Standard UI displays the attributes of the selected promotion, while the Smart UI option applies only to Trade Promotion Management promotions. This setting is separate from Retail Execution template controls such as Creation Platform, Selectable Promotion, and Mobility Color.","For automatic managed-package push upgrades, organizations using Trade Promotion Management must use the standard Smart UI. If an organization has an older custom Smart UI, the documentation requires a manual upgrade before participating in the push-upgrade process. The documentation doesn’t describe Smart UI as a mechanism for managing the Retail Execution promotion lifecycle."],connections:[{"planet":"tpm_master_data","desc":"Smart UI reads templates and master data for form configuration"}]},
    {id:"kpi-definitions",name:"KPI Definitions",icon:"\u{1F4CA}",desc:"KPI Definitions specify the individual measures used to evaluate promotions in Consumer Goods Cloud. Definitions can identify a KPI type, technical name, description, aggregation level, editability, read-only behavior, and sales organization. KPI Definitions are organized through KPI Sets, which can be mapped to business processes by using business templates. KPIs at a parent level are read-only aggregations of child KPIs.",tags:["cgcloud__KPI_Definition__c","cgcloud__KPI_Set__c"],docs:["A KPI Set is a list of individual KPIs or measures used to evaluate promotions. Business templates map KPI Sets to business processes, allowing the applicable measures to be associated with template-driven processes. The sales organization supports market-specific configuration of these definitions and sets.","The documented KPI model distinguishes editable measures from parent-level values that are read-only aggregations of child KPIs. Conditions can be configured as Read KPI definitions and their values can be used in promotions and account plan calculations. The documentation doesn’t establish that promotion KPIs roll up into account plan P&L."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.tpm_concept_permission_sets_users.htm&type=5&language=en_US",connections:[{"planet":"analytics","desc":"KPI definitions drive real-time reporting and dashboards"},{"planet":"account_planning","desc":"KPI sets are shared between promotions and account plans"}]},
    {id:"promotion-push",name:"Push Promotions",icon:"\u{1F4E4}",desc:"Push Promotions use Promotion Template Hierarchy to extend or push promotions through different levels of customer hierarchies. Promotion Push Status stores the status and statistics for each promotion push process. Push status records apply only to promotions selected for that process. This mechanism is distinct from the Key Account Manager (KAM) persona that manages promotions.",tags:["cgcloud__Promotion__c","cgcloud__Account_Trade_Org_Hierarchy__c"],docs:["A Promotion Template Hierarchy is a template for promotion hierarchies that extend or push promotions at different customer hierarchy levels. A parent Promotion Template can be associated with a child Promotion Template, and the association specifies which components are copied to the derived child promotion. For Retail Execution promotions, documented copied components include Tactics and Tactic Products.","Promotion Push Status tracks the status and statistics of each push process for the selected promotions. The push mechanism uses configured customer hierarchy levels rather than an actor called a KAM Agent. Consumer Goods Cloud documents the Key Account Manager (KAM) as the user persona who manages promotions, while Agentforce is separately documented as suggesting products and promotions and automating other Retail Execution tasks."],connections:[{"planet":"tpm_master_data","desc":"Push promotions follow the trade org hierarchy structure"}]}
  ],
  dataFlow: ["Maintain customer and product master data, customer hierarchies, customer sets, and applicable product listings.","Configure Promotion Templates, Tactic Templates, KPI Sets, and their required template associations.","Create a Sellable Promotion for a customer or customer set, and add tactics and eligible products.","Extend or push the promotion through configured customer hierarchy levels when Promotion Template Hierarchy is used.","Prepare eligible promotions and promoted products for Retail Execution visits and orders, and use retail reporting for supported performance insights.","Rely on Agentforce and Data Cloud for their own separately documented insight, suggestion, and segmentation capabilities outside this promotion lifecycle."],
  connections: [{"planet":"tpm_master_data","desc":"Promotions use customer and product master data"},{"planet":"funds_budgets","desc":"Promotion tactics consume allocated fund budgets"},{"planet":"claims","desc":"Executed promotions generate claims for retailer compensation"},{"planet":"account_planning","desc":"Promotion KPIs roll up into account plan P&L"},{"planet":"analytics","desc":"Promotion performance is tracked via real-time reporting"},{"planet":"products_assortments","desc":"Product assortments define available products for promotions"},{"planet":"agentforce","desc":"Agentforce provides separate promotion-suggestion capabilities"},{"planet":"data_cloud","desc":"Promotion data feeds accrual calculations and segmentation"}]
},

funds_budgets: {
  packages: ["consumergoods"],
  name: "Funds & Budgets",
  icon: "\u{1F4B0}",
  color: "#c084fc",
  description: "Funds & Budgets in Consumer Goods Cloud controls promotional budgets allocated to Key Account Managers. Finance managers create funds for customers and for customer-category or customer-brand combinations, anchored to customer and product master data. Rate-Based Funding supports budgets tied to sales volume or revenue percentages, while multi-fund transactions structure complex operations across funds. Fund allocation supports promotion tactics and account plan targets, claim settlements debit balances, and KPI reporting tracks utilization.",
  components: [
    {id:"fund-management",name:"Fund Management",icon:"\u{1F3E6}",desc:"Fund Management in Consumer Goods Cloud controls promotional budgets allocated to Key Account Managers. Finance managers create funds for customers and for customer-category or customer-brand combinations, with validity periods, currency, budget, commitment, remaining balance, and overdraft settings. Funds provide budgets for promotion tactics, align with account plan targets, and are anchored to customer and product master data.",tags:["cgcloud__Fund__c","cgcloud__Fund_Template__c"],docs:["A fund records its account, fund template, currency, budget, committed amount, remaining amount, validity period, status, and sales organization. It can also reference a product hierarchy, allowing funding to be associated with customer and product master data. The Overdraft Allowed setting indicates whether spending can exceed the available fund amount.","Fund templates define reusable fund types and settings, including currency, sales organization, KPI set, and overdraft allowance. Funds created from these templates provide budgets for promotion tactics and support allocation aligned with account plan targets. Claim settlements debit fund balances, while fund utilization can be tracked through KPI reporting."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.tpm_concept_admin_fund_management.htm&type=5&language=en_US",connections:[{"planet":"promotions","desc":"Funds pay for promotion tactics"},{"planet":"claims","desc":"Claims settle against fund balances"}]},
    {id:"rate-based-funding",name:"Rate-Based Funding",icon:"\u{1F4C8}",desc:"Rate-Based Funding in Consumer Goods Cloud provides budgets tied to rates, including funding based on sales volume or a percentage of revenue. Rate-based funding records associate an account, product hierarchy, fund, rate type, rate, validity period, and sales organization. Parent and child relationships support linked rate-based funding structures across accounts.",tags:["cgcloud__Rate_Based_Funding__c","cgcloud__RBF_Template__c","cgcloud__Parent_RBF__c"],docs:["A rate-based funding record identifies the account and product hierarchy to which a rate applies. Its rate type and rate define the funding basis, while the valid-from and valid-through dates control the applicable period. The resulting funding is associated with a fund and segmented by sales organization.","RBF templates provide reusable configuration through a technical name, rate type, KPI set, and sales organization. A rate-based funding record can reference a parent rate-based funding record, and Parent RBF records explicitly associate parent and child rate-based funding records with an account. These relationships support structured funding arrangements while retaining links to customer and product master data."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.tpm_concept_admin_fund_management.htm&type=5&language=en_US",connections:[{"planet":"tpm_master_data","desc":"RBFs are anchored to customer and product combinations"},{"planet":"analytics","desc":"RBF values are driven by KPI calculations"}]},
    {id:"multi-fund-transactions",name:"Multi-Fund Transactions",icon:"\u{1F4B1}",desc:"Multi-Fund Transactions in Consumer Goods Cloud support budget operations that involve multiple funds. A transaction header defines the transaction type, template, status, total amount, transaction date, and sales organization. Related transactions and rows allocate amounts to individual funds and identify the transaction direction and row type.",tags:["cgcloud__Fund_Transaction_Header__c","cgcloud__Fund_Transaction__c","cgcloud__Fund_Transaction_Row__c","cgcloud__Fund_Transaction_Template__c"],docs:["A Fund Transaction Header groups the entries for a fund operation and stores its total amount and processing status. Each Fund Transaction record links the header to a specific fund, records an amount, and identifies the transaction direction. This structure allows one header to coordinate entries across multiple funds.","Fund Transaction Rows provide additional line-level detail by identifying a row type, amount, fund, and parent fund transaction. Fund Transaction Templates define reusable transaction types and associate them with a KPI set and sales organization. Together, headers, transactions, and rows provide the record structure for complex multi-fund budget operations."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.tpm_concept_admin_fund_management.htm&type=5&language=en_US",connections:[{"planet":"claims","desc":"Fund transactions record claim settlement debits"},{"planet":"tpm_master_data","desc":"Transactions scoped by sales organization"}]},
    {id:"fund-kpis",name:"Fund KPIs",icon:"\u{1F4CA}",desc:"Fund KPIs in Consumer Goods Cloud use KPI sets associated with fund, rate-based funding, and fund transaction templates. The Assessment Indicator Definition object, with API name AssessmentIndicatorDefinition, stores key performance indicators or metrics and defines each metric’s data type. Fund utilization can be tracked through KPI reporting without treating cgcloud__KPI_Definition__c as the KPI definition object.",tags:["cgcloud__KPI_Definition__c","cgcloud__KPI_Set__c"],docs:["The Assessment Indicator Definition object stores KPIs or metrics, and its defining attribute is the metric data type. Supported data types include numerical, decimal, text, date-time, and boolean. This object is identified by the API name AssessmentIndicatorDefinition.","A KPI Set is a list of individual KPIs or measures that can be mapped to a business process through business templates. Fund Template, RBF Template, and Fund Transaction Template records each include a KPI Set reference, enabling templates to associate the applicable measures with their processes. KPIs at a parent level are read-only aggregations of child KPIs, and fund utilization is available for KPI reporting and analytics."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.tpm_concept_admin_fund_management.htm&type=5&language=en_US",connections:[{"planet":"analytics","desc":"Fund KPIs feed real-time budget reports"},{"planet":"account_planning","desc":"Fund utilization reflects in account plan P&L"}]}
  ],
  dataFlow: ["Anchor funds and rate-based funding to customer and product master data.","Allocate fund budgets in line with account plan targets.","Assign fund budgets to promotion tactics.","Post multi-fund transactions and update committed and remaining amounts.","Debit fund balances when claims are settled.","Track fund utilization through KPI reporting and analytics."],
  connections: [{"planet":"promotions","desc":"Funds provide budgets for promotion tactics"},{"planet":"tpm_master_data","desc":"Funds are anchored to customer and product master data"},{"planet":"claims","desc":"Claim settlements debit fund balances"},{"planet":"account_planning","desc":"Fund allocation aligns with account plan targets"},{"planet":"analytics","desc":"Fund utilization tracked via KPI reporting"}]
},

claims: {
  packages: ["consumergoods"],
  name: "Claims",
  icon: "\u{1F4DD}",
  color: "#e879f9",
  description: "Claims in Consumer Goods Cloud represent retailer payment requests submitted as compensation for expenses incurred after promotion tactics are executed. Claims management covers creation or import, review and approval, and settlement through Accounts Receivable or Accounts Payable, with settlements debiting the associated fund balance. Customer relationships determine claim recipients and payers, while claim actuals affect account plan profitability. Claim KPIs support real-time settlement reporting, and claim data can be reconciled with accrual engine calculations in Data Cloud.",
  components: [
    {id:"claims-processing",name:"Claims Processing",icon:"\u{1F4DD}",desc:"Claims Processing manages retailer payment requests associated with executed promotion tactics in Consumer Goods Cloud. A claim records the customer account, claim type, requested and approved amounts, status, validity period, and relevant promotion, tactic, and fund. Settlement integrates with Accounts Receivable and Accounts Payable and debits the applicable fund balance. Claim actuals also affect account plan profitability and can be reconciled with accrual engine calculations in Data Cloud.",tags:["cgcloud__Payment__c","cgcloud__Payment_Template__c"],docs:["Retailers submit claims after promotion tactics are executed to request compensation for incurred expenses. Consumer Goods Cloud represents the request with cgcloud__Payment__c, including the account, claim type, requested amount, approved amount, and status. The record can also reference the promotion, tactic, fund, sales organization, and applicable validity dates.","Customer relationships identify claim recipients and payers, while the promotion and tactic references connect the request to the executed promotional activity. The fund reference identifies the balance affected by settlement. Valid From and Valid Thru provide the applicable period for the payment request.","After review and approval, claim settlement debits the associated fund balance and integrates with Accounts Receivable and Accounts Payable. The resulting actuals contribute to account plan profitability. Claim data can also be reconciled with accrual engine calculations in Data Cloud and used in settlement reporting."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.tpm_concept_admin_promotion.htm&type=5&language=en_US",connections:[{"planet":"promotions","desc":"Claims compensate retailers for executed promotion tactics"},{"planet":"funds_budgets","desc":"Claims settle against fund balances"}]},
    {id:"claims-approval",name:"Claims Approval",icon:"\u{2705}",desc:"Claims Approval controls whether a claim requires approval before settlement in Consumer Goods Cloud. The Approval Required setting on cgcloud__Payment_Template__c records this requirement, while requested and approved amounts and status are maintained on cgcloud__Payment__c. The provided documentation does not associate cgcloud__Approval_Code__c with claims; approval codes authenticate DSD transactions such as inventory check-out or cash check-in.",tags:["cgcloud__Approval_Code__c"],docs:["A payment template can identify whether approval is required through cgcloud__Approval_Required__c. Claim records separately retain the requested amount, approved amount, and current status. These values support review of the amount requested by the retailer and the amount accepted for settlement.","Approved claims can proceed to settlement against the referenced fund and through Accounts Receivable or Accounts Payable integration. Consumer Goods Cloud does not use the DSD Approval Code mechanism as a claims authorization control in the provided documentation. Approval Code is documented for warehouse checkers or cashiers to authenticate critical DSD transactions, including inventory check-out and cash check-in."],connections:[{"planet":"tpm_master_data","desc":"Approval codes are tied to user roles and settings"}]},
    {id:"claims-import",name:"Claims Import",icon:"\u{1F4E5}",desc:"Claims Import brings retailer payment requests into Consumer Goods Cloud for processing and settlement. Imported claim data is represented by cgcloud__Payment__c and can include customer, claim type, amounts, status, validity dates, and promotion-related references. The imported data can then follow the same approval, fund settlement, reporting, and reconciliation lifecycle as other claims.",tags:["cgcloud__Payment__c"],docs:["Retailer payment requests can be loaded as claim records for processing in Consumer Goods Cloud. Each record can preserve the account, claim type, requested amount, approved amount, status, and validity period. Promotion, tactic, fund, and sales organization references provide the business context required for downstream handling.","Customer relationships determine the relevant claim recipients and payers after the data is available in Consumer Goods Cloud. Imported claims can be reviewed and, when required, approved before settlement through Accounts Receivable or Accounts Payable. The resulting claim data can be reconciled with accrual engine calculations in Data Cloud."],connections:[{"planet":"tpm_master_data","desc":"Imported claims are matched to customer master records"}]},
    {id:"claims-kpis",name:"Claims KPIs",icon:"\u{1F4CA}",desc:"Claims KPIs connect claim settlement data with performance measurement and reporting in Consumer Goods Cloud. A payment template can reference cgcloud__KPI_Set__c, which is a list of KPIs or measures used to evaluate promotions and can be mapped to a business process through business templates. Claim KPIs support real-time settlement reporting, while claim actuals contribute to account plan profitability. Parent-level KPIs are read-only aggregations of their child KPIs.",tags:["cgcloud__KPI_Definition__c","cgcloud__KPI_Set__c"],docs:["The cgcloud__KPI_Set__c reference on cgcloud__Payment_Template__c associates a set of measures with the payment template. Consumer Goods Cloud defines a KPI set as a list of individual KPIs or measures that help evaluate promotions. Business templates can map KPI sets to a business process.","Claim KPIs feed settlement reporting and provide visibility into claim-related results. Claim actuals also affect account plan profitability, connecting settlement outcomes with account-level planning. Parent-level KPIs are read-only and aggregate the values of their child KPIs."],connections:[{"planet":"analytics","desc":"Claim KPIs feed real-time settlement reports"},{"planet":"account_planning","desc":"Claim actuals reflect in account plan P&L"}]}
  ],
  dataFlow: ["Receive a retailer claim for an executed promotion tactic.","Identify the recipient and payer from customer relationships.","Create or import the claim with its amounts, status, dates, and promotion references.","Review the claim and record the approved amount when approval is required.","Settle the claim through Accounts Receivable or Accounts Payable and debit the fund balance.","Reconcile claim data with accrual engine calculations and report claim KPIs."],
  connections: [{"planet":"promotions","desc":"Claims compensate executed promotion tactics"},{"planet":"funds_budgets","desc":"Claim settlements debit fund balances"},{"planet":"tpm_master_data","desc":"Customer relationships determine claim recipients and payers"},{"planet":"analytics","desc":"Claim KPIs feed into real-time settlement reporting"},{"planet":"account_planning","desc":"Claim actuals impact account plan profitability"},{"planet":"data_cloud","desc":"Claim data reconciled with accrual engine calculations"}]
},

account_planning: {
  packages: ["consumergoods"],
  name: "Account Planning",
  icon: "\u{1F4C8}",
  color: "#2dd4bf",
  description: "Account planning provides KAMs with a profit-and-loss overview for each customer and product combination over time. Customer Business Plans store aggregated KPIs that can be manually adjusted, enabling scenario planning and strategic decision-making for sales targets and promotional investment.",
  components: [
    {id:"customer-business-plan",name:"Customer Business Plans",icon:"\u{1F4CB}",desc:"Stores data for an account and business year combination with one or more product categories. KAMs can enter or manually adjust KPI data with changes cascading to promotions and account plans.",tags:["cgcloud__Account_Plan__c"],docs:["Customer Business Plans store data for an account and business year combination with one or more product categories, forming the foundation of account-level planning in Consumer Goods Cloud. The Customer Business Plan object (cgcloud__Account_Plan__c) allows KAMs to enter or manually adjust KPI data, with changes cascading to promotions and account plans. This is where management-defined fiscal year targets are broken down to the account level for day-to-day execution.","To set up Customer Business Plans, admins configure customer templates that determine the KPI sets and product aggregation levels available in the plan. A management team first defines targets to achieve in the current fiscal year based on the team's performance in the previous year. These country- or region-level targets are then broken down and loaded into Customer Business Plans at the account level, giving KAMs a clear picture of what they need to achieve.","In daily workflow, KAMs use Customer Business Plans to plan promotions against their targets, monitor actual performance versus plan, and adjust KPI values as market conditions change. When KPIs are changed in a Customer Business Plan, the changes reflect in promotions and the account plan P&L. KAMs can download data from account plan P&L and Customer Business Plan scenarios to share insights across product hierarchy levels, enabling collaborative decision-making with management."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.tpm_account_plan_cbp_create.htm&type=5&language=en_US",connections:[{"planet":"promotions","desc":"Business plan targets cascade to individual promotions"},{"planet":"analytics","desc":"Business plan KPIs feed real-time P&L reports"}]},
    {id:"account-pl",name:"Account P&L View",icon:"\u{1F4B5}",desc:"Shows the aggregated KPI for a customer and product combination for a timeframe. Displays planned versus actual values across promotion, fund, and claim KPIs in a hierarchical grid.",tags:["cgcloud__Account_Plan__c","cgcloud__KPI_Set__c"],docs:["The Account P&L View shows the aggregated KPI for a customer and product combination over a defined timeframe, providing KAMs with a comprehensive profit and loss overview of their accounts. It displays planned versus actual values across promotion, fund, and claim KPIs in a hierarchical grid, enabling managers to see exactly how each account is performing against its targets. The Account P&L serves as the central financial dashboard for trade promotion management at the account level.","The Account P&L is configured through the customer template and KPI set mappings. Account plans can be created to group different KPIs, aggregate weekly and monthly data, and present a unified financial view. Admins can create separate account plan P&Ls for different business needs, and the view automatically incorporates data from promotions, funds, and claims.","KAMs use the Account P&L view as their primary dashboard for account-level financial performance. Fund allocations, promotional spending, and claim actuals all appear in a single consolidated view, making it straightforward to identify variances between planned and actual performance. The hierarchical grid structure allows users to drill down from top-level account metrics to individual product categories and promotional activities, supporting both high-level oversight and detailed analysis."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.tpm_account_plan_create_view.htm&type=5&language=en_US",connections:[{"planet":"funds_budgets","desc":"Fund allocations appear in the P&L view"},{"planet":"claims","desc":"Claim actuals are reflected in the P&L"}]},
    {id:"scenario-planning",name:"Scenario Planning",icon:"\u{1F52E}",desc:"KAMs can download data from account plan P&L and model different promotional investment strategies. Scenarios enable what-if analysis by adjusting KPI inputs and observing the impact on profitability.",tags:["cgcloud__Account_Plan__c"],docs:["Scenario Planning enables KAMs to model different promotional investment strategies by downloading data from the account plan P&L and adjusting KPI inputs to observe the impact on profitability. This what-if analysis capability allows teams to compare multiple investment scenarios before committing promotional budgets, reducing the risk of suboptimal spending decisions. Scenarios are created within the Customer Business Plan interface and can be saved for comparison during planning reviews.","KAMs can create and edit scenarios within the Customer Business Plan interface. Each scenario adjusts KPI values such as planned volume, revenue targets, or promotional spend, and the KPI calculation engine recalculates the resulting P&L impact in real time. Scenarios leverage the same calculation engine as the live account plan, ensuring consistency between modeled and actual results.","In practice, Scenario Planning is most commonly used during annual planning cycles and mid-year budget reviews. KAMs can model the impact of increasing promotional investment in a particular product category, shifting budget from one tactic type to another, or adjusting volume targets based on market intelligence. The ability to compare scenarios side by side helps management make data-driven decisions about where to allocate limited promotional resources for maximum return."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.tpm_cbp_scenario_edit_kpis.htm&type=5&language=en_US",connections:[{"planet":"promotions","desc":"Scenarios model promotion investment alternatives"},{"planet":"analytics","desc":"Scenario KPIs leverage the same calculation engine"}]},
    {id:"sub-accounts",name:"Sub-Account Planning",icon:"\u{1F4CA}",desc:"Sub-accounts are subsets of accounts whose KPIs aggregate to parent account KPIs. Supports granular planning at store-type level while maintaining rolled-up visibility.",tags:["cgcloud__Sub_Account__c"],docs:["Sub-Account Planning allows organizations to break down account-level planning into more granular segments using sub-account records (cgcloud__Sub_Account__c). Sub-accounts are subsets of accounts whose KPIs aggregate to parent account KPIs in the account plan. For example, a retailer headquarter account might have sub-accounts for supermarkets and hypermarkets, each tracking separate volume and revenue targets.","Sub-accounts derive their structure from the customer master hierarchy, and their configuration is managed through the same customer template and KPI set framework as the parent account. When KPIs are updated at the sub-account level, the changes automatically roll up to the parent account's P&L view, maintaining consistency across the planning hierarchy. This rollup behavior ensures that headquarter-level visibility is always accurate regardless of how granularly individual sub-accounts are managed.","In practice, sub-account planning enables KAMs to tailor their promotional strategies for different store formats or channels within a single retailer relationship. A KAM managing a national grocery chain can set distinct volume targets for convenience stores versus large-format stores, plan different tactical mixes for each, and still see a unified P&L at the headquarter level. This granularity supports more precise budget allocation and performance tracking across diverse retail formats."],connections:[{"planet":"tpm_master_data","desc":"Sub-accounts derive from the customer master hierarchy"}]},
    {id:"manual-inputs",name:"Manual Inputs",icon:"\u{270F}\u{FE0F}",desc:"Allows KAMs to manually enter or adjust KPI values in account plans. Manual inputs override calculated values and cascade changes through the P&L.",tags:["cgcloud__Account_Plan__c"],docs:["Manual Inputs allow KAMs to directly enter or adjust KPI values in account plans, overriding the system-calculated values when business knowledge warrants a different figure. Manual input overrides cascade through the P&L calculation, updating all downstream KPIs that depend on the adjusted value. This capability bridges the gap between automated calculations and real-world business intelligence that cannot be captured in formulas alone.","By default, you can enter up to 5,000 manual inputs for an account plan. However, if this limit is not sufficient, admins can increase the limit for manual inputs to up to 100,000 per account plan. The manual input feature is available within the Customer Business Plan and account plan P&L interfaces, where KAMs can directly edit KPI cells and see the cascading impact on related measures.","KAMs typically use manual inputs during planning cycles to incorporate market intelligence, competitive insights, or negotiation outcomes that are not reflected in historical data. For example, a KAM might manually adjust volume targets after negotiating a new shelf space agreement with a retailer, or override a revenue forecast based on knowledge of an upcoming competitor product launch. These adjustments are reflected in the KPI calculation engine and update the real-time reporting views accordingly."],connections:[{"planet":"analytics","desc":"Manual input overrides are reflected in KPI calculations"}]}
  ],
  dataFlow: ["Step 1: Management defines fiscal year targets by region and product category","Step 2: Targets are broken down to account level and loaded into customer business plans","Step 3: KAMs adjust plan KPIs manually and plan promotions against targets","Step 4: Promotion and claim actuals aggregate up into the account P&L view","Step 5: Variance analysis between planned and actual drives next-period planning decisions"],
  connections: [{"planet":"promotions","desc":"Promotion KPIs aggregate into account plan P&L"},{"planet":"funds_budgets","desc":"Fund allocation aligns with account plan investment targets"},{"planet":"tpm_master_data","desc":"Account hierarchies structure the planning framework"},{"planet":"claims","desc":"Claim actuals impact account plan profitability metrics"},{"planet":"analytics","desc":"Account plan KPIs feed real-time reporting dashboards"},{"planet":"agentforce","desc":"KAM Agent retrieves account performance measures"}]
},

analytics: {
  packages: ["consumergoods"],
  name: "Analytics & Reporting",
  icon: "\u{1F4CA}",
  color: "#60a5fa",
  description: "Analytics & Reporting unifies Consumer Goods Cloud analytics for Retail Execution and Trade Promotion Management. It calculates and reports promotion, account plan P&L, fund and budget, and claim settlement measures, while visit execution and store-level data support compliance and performance analysis. CRM Analytics provides standard territory, store, product, sales rep, and whitespace dashboards, and the advanced data model adds My Territory, Sales Manager Insights, and Account Insights. Data Cloud provides the unified data platform for advanced analytics and Einstein, while the documented revenue-uplift workflow uses CRM Analytics templates (Use Predictions to Power Sales, Store Revenue Story) whose predictions can feed a Next Best Action strategy for model-based visit recommendations.",
  components: [
    {id:"real-time-reporting",name:"Real-Time Reporting",icon:"\u{26A1}",desc:"Real-Time Reporting provides visit-related insights from data available in the Consumer Goods Cloud offline mobile app. It supports live reporting based on offline data and shows embedded visualizations based on pre-aggregated data. This approach gives field users timely execution information without requiring the more sophisticated reporting available through CRM Analytics.",tags:[],docs:["The Consumer Goods Cloud offline mobile app supports live reporting based on offline data. It uses pre-aggregated data to show visit-related insights in embedded visualizations. This reporting approach is intended for operational information needed during field execution.","Use CRM Analytics when reporting requirements are more sophisticated and don’t require live data. CRM Analytics apps use dataflows to import current data, and administrators can schedule an app refresh every day. This separates operational reporting in the offline mobile app from broader performance analysis in CRM Analytics."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.tpm_rtr_concept_configure_rtr.htm&type=5&language=en_US",connections:[{"planet":"promotions","desc":"RTR surfaces promotion KPIs in real time"},{"planet":"account_planning","desc":"RTR shows account plan P&L measures"}]},
    {id:"kpi-engine",name:"KPI Calculation Engine",icon:"\u{2699}\u{FE0F}",desc:"The KPI Calculation Engine calculates and organizes measures used to evaluate retail execution, promotions, and account plans in Consumer Goods Cloud. Retail Store KPI records define metrics and targets, while Retail Visit KPI records capture actual results during visits. KPI sets group measures for promotion evaluation, and parent-level KPIs aggregate child KPI values. Account plan P&L, promotion, fund and budget, and claim settlement measures flow through this analytical scope.",tags:["cgcloud__KPI_Definition__c","cgcloud__KPI_Set__c"],docs:["Assessment Indicator Definition stores KPIs or metrics and defines each metric’s data type. Retail Store KPI defines metrics and target compliance values for products, categories, promotions, assets, and in-store locations. Retail Visit KPI stores the actual information captured during a visit against the applicable assessment indicator definitions and target values.","KPI Set provides a list of individual KPIs or measures used to evaluate promotions and can be mapped to business processes through business templates. KPIs at a parent level are read-only aggregations of child KPIs. Subaccounts also contribute their KPIs to parent account KPIs in account plans.","Conditions are interfaced with Processing Services and can be configured as Read KPI definitions. Their values can be used in promotions and account plan calculations. Within the broader Analytics & Reporting scope, calculated measures also support account plan P&L analysis, fund utilization and budget tracking, and claim settlement analysis."],docUrl:"https://help.salesforce.com/s/articleView?language=en_US&id=sf.concept_kpi_configurations.htm&type=5",connections:[{"planet":"promotions","desc":"Calculates promotion summary sheet KPIs"},{"planet":"funds_budgets","desc":"Calculates fund utilization and remaining budget"}]},
    {id:"crm-analytics-dashboards",name:"CRM Analytics Dashboards",icon:"\u{1F4C9}",desc:"CRM Analytics Dashboards provide actionable retail and account performance insights for Consumer Goods Cloud. The standard analytics app includes Territory Performance, Store Performance, Product Performance, Sales Rep Performance, and Whitespace Analysis dashboards. The advanced data model adds account-level dashboards such as My Territory, Sales Manager Insights, and Account Insights. Embedded dashboards place store, account, last-visit, whitespace, and individual performance insights on relevant Lightning pages.",tags:[],docs:["Analytics for Consumer Goods helps sales managers increase sales, improve store compliance, identify stores at risk, and maximize sales rep effectiveness. Sales reps receive store-level insights into visits, sales, compliance, and top-selling products. The in-app dashboards cover territory, store, product, sales rep, and whitespace performance, while embedded dashboards provide insights in the context of Salesforce records.","The Territory Performance dashboard analyzes sales trends, geographic changes, and top-performing accounts, products, or categories. Store Performance identifies stores that need attention and shows how visits and retail execution KPIs affect compliance and revenue. Product Performance analyzes products, categories, brands, assortments, promotions, and newly launched products, while Whitespace Analysis identifies stores with unused potential for products or categories.","Analytics for Consumer Goods - Advanced Data Model provides account-level insights. Its in-app dashboards include Account Performance, Competitor Analytics, My Territory, Product Performance, Sales Manager Insights, Sales Representative Summary, Store Participation and Compliance Analysis, and Whitespace Analysis. Embedded dashboards include Last Account Visit, Account Insights, My Performance, and Whitespace Analysis.","Administrators enable CRM Analytics, assign the applicable administrator and user permission sets, verify required source data, and create an app from the appropriate template. The app creation process includes dataflows that import the latest data into CRM Analytics. Administrators can schedule daily refreshes and share the resulting app with authorized users."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.retail_admin_analytics_deploy.htm&type=5&language=en_US",connections:[{"planet":"visit_execution","desc":"Dashboards visualize visit execution metrics"},{"planet":"accounts_stores","desc":"Store-level metrics power compliance dashboards"}]},
    {id:"uplift-prediction",name:"Uplift Prediction",icon:"\u{1F52E}",desc:"Uplift Prediction uses CRM Analytics and Einstein Discovery to model opportunities for increasing store revenue in Consumer Goods Cloud. The documented workflow can ingest external point-of-sale data, use Consumer Goods Cloud data, or start from an uploaded dataset. Prebuilt templates generate training and scoring datasets before the Store Revenue Story deploys a revenue uplift model. Predictions can then contribute to model-based visit recommendations.",tags:[],docs:["The External Sales Data template maps and synchronizes an external point-of-sale data source into Consumer Goods Cloud. The Use Predictions to Power Sales template consumes that dataset, or a dataset generated from Consumer Goods Cloud data or a CSV file. Its recipes perform transformations and aggregations to produce feature, training, and scoring datasets.","The Store Revenue Story template consumes the generated training and scoring datasets and deploys the model. The resulting model contains insights for maximizing store revenue, and its datasets contain the final scoring data. A related workflow can write prediction results back to a custom object in the Salesforce org through an output connection and recipe.","Model-based visit recommendations use prediction data in a Next Best Action strategy. The mapped data can include the model score, leading predictors, their impacts, the applicable retail store, and the prediction validity dates. When a sales manager requests recommendations for a date range, Consumer Goods Cloud runs the strategy for each date in the interval and generates the applicable recommendations."],docUrl:"https://help.salesforce.com/s/articleView?language=en_US&id=sf.tpm_admin_analytics_tpo.htm&type=5",connections:[{"planet":"promotions","desc":"Predicts uplift volume for planned promotions"},{"planet":"account_planning","desc":"Predicted uplift informs account plan targets"}]},
    {id:"kpi-export",name:"KPI Export",icon:"\u{1F4E4}",desc:"KPI Export makes calculated and captured Consumer Goods Cloud measures available to downstream analytics structures. Retail Visit KPI data can be ingested by CRM Analytics and mapped through the Consumer Goods Cloud data kit into the Retail Visit KPI data model object in Data Cloud. Scheduled CRM Analytics dataflows refresh analytical datasets with current source data. The documentation does not describe a separate interactive KPI export operation.",tags:[],docs:["Analytics for Consumer Goods uses dataflows to import current Salesforce data into CRM Analytics. Administrators schedule the analytics app to refresh so that its dataflows run in the correct order and dashboards use current information. RetailVisitKpi is one of the required source objects for the standard analytics app.","The Consumer Goods Cloud data kit includes a RetailVisitKPI data stream and maps its attributes to the Retail Visit KPI data model object in Data Cloud. The documented mapping includes the actual value, target value, their data types, product, product category, promotion, visit, assessment task, in-store location, and Assessment Indicator Definition references. Deploying the data streams makes this KPI information available within the Data Cloud data model."],connections:[{"planet":"data_cloud","desc":"Exported KPIs can be integrated into Data Cloud"}]},
    {id:"data-360-integration",name:"Data 360 Integration",icon:"\u{1F310}",desc:"Data Cloud for Consumer Goods Cloud integrates Consumer Goods Cloud with Data Cloud for account segmentation, consumer insights, and store-level product performance. Consumer Goods Cloud data kits install and deploy data streams, data lake objects, data transforms, and mappings to Data Cloud data model objects. Retail execution data such as accounts, retail stores, visits, Retail Visit KPIs, products, orders, promotions, and assortments can participate in the mapped model. Data Cloud provides the unified data platform used by advanced analytics and Einstein capabilities.",tags:[],docs:["To integrate Consumer Goods Cloud with Data Cloud, administrators connect Data Cloud to the Salesforce CRM org and verify the Salesforce Standard Data Model package. They add the required object and field access to the Data Cloud Salesforce Connector permission set. The Consumer Goods Cloud data kit is then installed in the Salesforce org and deployed from the Data Streams tab.","Consumer Goods Cloud provides data kits for Retail Execution Base, Retail Execution Enhanced, and Trade Promotion Management. The data kits deploy source objects into data streams and map their data lake objects to Data Cloud data model objects. Retail Execution Enhanced includes mapped data for advanced orders, advanced promotions, tactics, product hierarchies, visits, visit jobs, accounts, products, stores, assortments, and Retail Visit KPIs.","Administrators can configure data lake objects and use streaming data transforms to clean or reshape ingested data before mapping it to target objects. The deployed mappings make account, store, visit, sales, product, promotion, and compliance data available in Data Cloud. Data Cloud segments can then be built from data model object attributes and activated to supported targets.","Data Cloud segmentation supports customer groups derived from B2B and B2C data. Segment results can also be saved to Consumer Goods Cloud custom objects through an Apex integration when required. This unified data foundation supports analytics and Einstein use cases that consume customer and retail execution information."],connections:[{"planet":"data_cloud","desc":"Data 360 leverages Data Cloud for unified analytics"}]}
  ],
  dataFlow: ["Capture visit execution metrics and store-level performance data.","Calculate promotion KPIs, account plan P&L measures, fund and budget utilization, and claim settlement metrics.","Pre-aggregate operational measures for live reporting in the Consumer Goods Cloud offline mobile app.","Refresh CRM Analytics datasets and review territory, store, product, sales rep, whitespace, and account insights.","Ingest mapped accounts, stores, visits, products, orders, promotions, and KPIs into Data Cloud.","Use CRM Analytics templates to deploy a revenue-uplift model from Consumer Goods Cloud or external sales data, and feed its predictions into model-based visit recommendations."],
  connections: [{"planet":"promotions","desc":"Promotion KPIs are calculated and reported"},{"planet":"account_planning","desc":"Account plan P&L measures flow through the KPI engine"},{"planet":"visit_execution","desc":"Visit execution metrics feed Retail Execution dashboards"},{"planet":"accounts_stores","desc":"Store-level data powers compliance and performance analytics"},{"planet":"data_cloud","desc":"Data Cloud provides unified data platform for advanced analytics"},{"planet":"funds_budgets","desc":"Fund utilization and budget KPIs are tracked"},{"planet":"claims","desc":"Claim settlement metrics feed P&L analysis"},{"planet":"einstein_ai","desc":"Einstein and analytics share the same underlying data platform"}]
},

agentforce: {
  packages: ["consumergoods"],
  name: "Agentforce",
  icon: "\u{1F916}",
  color: "#818cf8",
  description: "AI-powered agents for both Retail Execution and Trade Promotion Management. The TPM KAM Agent helps key account managers view promotion and account measures, copy promotions, and update existing promotions using 13 custom actions. The Retail Execution agents provide customer service assistance and visit planning support.",
  components: [
    {id:"kam-agent",name:"TPM KAM Agent",icon:"\u{1F464}",desc:"Agentforce Employee Agent configured for TPM Key Account Managers. Supports viewing promotion and account measures, creating and updating promotions via BO API workflows.",tags:[],docs:["The TPM KAM Agent is an Agentforce Employee Agent specifically configured for Trade Promotion Management Key Account Managers. It supports viewing promotion and account measures, copying promotions, and updating existing promotions using 13 custom actions that interact with the TPM Business Object API workflows. The agent allows KAMs to perform complex TPM tasks through natural language requests rather than navigating multiple screens and menus.","The KAM Agent is built on the Agentforce platform and uses an Agentforce Employee Agent template. Admins set up the agent by enabling Agentforce, configuring agent topics that group related TPM tasks, and defining context variables that map the user's sales organization, permissions, and data filters to appropriate actions. The agent requires the Agentforce for Consumer Goods Cloud add-on license and consumes Flex Credits and Einstein Requests.","In daily workflow, a KAM opens the agent interface and submits natural language requests such as asking for promotion performance measures for a specific account, requesting to copy a successful promotion to a new time period, or updating tactic details on an existing promotion. The LLM evaluates the request against configured topics, selects the appropriate custom actions, executes them via the Business Object API, and presents the results with actionable next steps. This significantly reduces the time required for routine TPM tasks."],connections:[{"planet":"promotions","desc":"KAM Agent reads and updates promotion records"},{"planet":"account_planning","desc":"KAM Agent retrieves account plan measures"}]},
    {id:"agent-actions",name:"Agent Actions",icon:"\u{2699}\u{FE0F}",desc:"Thirteen custom actions including Read User Sales Organization, Execute Promotion BO API Workflow, Retrieve Account/Promotion Measures, Get Products, and Validate TPM Account.",tags:[],docs:["Agent Actions are the thirteen custom actions that power the TPM KAM Agent, providing specific capabilities for interacting with Consumer Goods Cloud data and workflows. Key actions include Read User Sales Organization, Execute Promotion BO API Workflow, Retrieve Account Measures, Retrieve Promotion Measures, Get Products, Validate TPM Account, and several others that cover the full range of TPM operations a KAM performs. Each action encapsulates a discrete business operation that the agent can invoke based on the user's natural language request.","Each action is configured as a custom agent action within the Agentforce framework, with defined input parameters, output schemas, and API endpoints. The actions interact with the TPM Business Object API to read data from and write data to CG Cloud objects and the processing service. Admins can customize action configurations and add new actions as business requirements evolve, following Salesforce's standard agent action development patterns.","The actions work together in orchestrated sequences. For example, when a KAM asks the agent to show promotion performance for a specific account, the agent first executes the Validate TPM Account action to confirm access, then uses Read User Sales Organization to establish context, and finally calls Retrieve Promotion Measures to fetch the data. This orchestration happens automatically based on the LLM's interpretation of the user's request and the configured topic instructions."],docUrl:"https://help.salesforce.com/s/articleView?id=ai.copilot_actions_custom.htm&language=en_US",connections:[{"planet":"tpm_master_data","desc":"Actions read sales org, accounts, and products"},{"planet":"analytics","desc":"Actions retrieve measures from real-time reports"}]},
    {id:"rex-agents",name:"Retail Execution Agents",icon:"\u{1F6CD}\u{FE0F}",desc:"Agentforce for Retail Execution includes Customer Service Assistance for handling store inquiries and the Visit Assistant for helping field reps plan and execute store visits.",tags:[],docs:["Retail Execution Agents bring Agentforce capabilities to the field sales side of Consumer Goods Cloud, including Customer Service Assistance for handling store inquiries and the Visit Assistant for helping field reps plan and execute store visits. These agents streamline Retail Execution by automating key tasks such as generating account and visit insights, suggesting products and promotions, and creating visits. They are built on the Agentforce platform and operate on both the Consumer Goods Cloud mobile and desktop apps.","The Customer Service Assistance agent provides AI-driven insights on store performance, compliance, restocks, and visit schedules. It uses account summaries to enhance customer interactions and drives sales through intelligent product recommendations. The Retail Execution Visit Assistant is an autonomous AI agent that helps field reps, supervisors, and other Retail Execution users access and analyze key data and perform tasks related to retail visits directly within their workflow.","Agentforce for Retail Execution works on the Consumer Goods Cloud mobile and desktop apps but requires online mode on mobile devices. The agents support English (en_US) locale and consume Flex Credits, Einstein Requests, and Data Services Credits. Agents can generate account performance data, retrieve orders by account or visit, get customer tasks, and identify records, making field reps more efficient during store visits.","Usage of Agentforce impacts credit consumption against Flex Credits, Einstein Requests, and Data Services Credits. Before deployment, organizations should work with their Salesforce account team to confirm license availability and plan credit usage. Agentforce does not work in the Modeler simulator app and requires the Agentforce for Consumer Goods Cloud add-on license."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.retail_agentforce_cg_mobile_app_intro.htm&language=en_US",connections:[{"planet":"visit_planning","desc":"Visit Assistant helps plan optimal visit routes"},{"planet":"visit_execution","desc":"Visit Assistant guides in-store task execution"}]},
    {id:"agent-topics",name:"Agent Topics & Context",icon:"\u{1F4AC}",desc:"Agent topics group related tasks. Context variables ensure the agent acts consistently by mapping sales organization, user permissions, and data filters to appropriate actions.",tags:[],docs:["Agent Topics group related tasks within the Agentforce framework and define how the AI agent interprets and responds to user requests. Each topic contains a set of instructions, associated actions, and scope definitions that guide the LLM in selecting the appropriate actions for a given request. Topics ensure that the agent acts consistently by constraining which capabilities are available for different categories of user interactions.","Admins configure topics using the Agentforce setup interface, defining the topic name, description, instructions for the LLM, and the set of actions available within that topic. Context variables are defined to map sales organization, user permissions, and data filters to appropriate actions, ensuring that the agent only accesses data and performs operations that the current user is authorized for. Best practices for writing topic instructions are provided in the Agentforce documentation.","In practice, topics provide the organizational structure that makes the agent reliable and predictable. For example, a TPM topic might group all promotion-related actions together with instructions about when to validate account access, how to handle ambiguous product references, and which measures to present by default. This topic-based architecture ensures that the agent's behavior aligns with business processes and security requirements across different sales organizations and user roles."],docUrl:"https://help.salesforce.com/s/articleView?id=ai.copilot_topics.htm&type=5&language=en_US",connections:[{"planet":"tpm_master_data","desc":"Context variables pull user and sales org settings"}]}
  ],
  dataFlow: ["Step 1: KAM opens the agent interface and submits a natural language request","Step 2: LLM evaluates the request against configured topics and selects appropriate actions","Step 3: Agent executes custom actions (retrieve measures, get accounts, validate access)","Step 4: Results are formatted and presented to the user with actionable next steps","Step 5: For update actions, agent executes BO API workflows to modify promotion records"],
  connections: [{"planet":"visit_planning","desc":"Visit Assistant supports field rep visit planning"},{"planet":"visit_execution","desc":"Retail Execution agents guide in-store task completion"},{"planet":"accounts_stores","desc":"Agents access store and account data for context"},{"planet":"promotions","desc":"KAM Agent manages promotion lifecycle"},{"planet":"account_planning","desc":"KAM Agent retrieves account performance measures"},{"planet":"mobile_app","desc":"Agents are accessible through the mobile app interface"}]
},

einstein_ai: {
  packages: ["consumergoods"],
  name: "Einstein AI",
  icon: "\u{1F9E0}",
  color: "#facc15",
  description: "Einstein AI in Consumer Goods Cloud covers predictive visit recommendations, generative account health assessments, warehouse inventory deviations, and Einstein Quick Insights. Store attributes and targets feed predictions, while visit recommendations influence visit planning priorities. Visit execution data trains and validates Einstein models, connecting recommendations to field execution outcomes. Product velocity insights inform van sales loading, and Einstein and analytics share the same underlying data platform.",
  components: [
    {id:"visit-recommendations",name:"Visit Recommendations",icon:"\u{1F4CD}",desc:"Visit Recommendations in Consumer Goods Cloud help sales managers and field reps identify stores for field visits, improve field efficiency, and pursue sales opportunities. Recommendations can be generated from flows, Next Best Action strategies, Apex actions, or prediction-based models. Store data provides predictive inputs, and recommendation results influence visit planning priorities. Visit execution outcomes provide data for training and validating Einstein models.",tags:["AiVisitRecommendation"],docs:["Einstein Visit Recommendation lets sales managers and field reps request store recommendations for a target date or date range and schedule visits from the results. Administrators enable Einstein Visit Recommendation and configure one or more strategies for different business requirements. Strategies can consider criteria such as upcoming promotions, open cases, prior out-of-stock findings, and the time since a store was last visited. Salesforce stores the generated recommendations so users can review their reasons and act on them during visit planning.","Administrators can implement a strategy with an autolaunched flow, a Next Best Action strategy, or an Apex action invoked from a flow. Flow strategies use SiteIds and TargetDate as input variables and return RecommendedSiteIds and VisitRecommendationReasons. The documentation recommends Apex for scalable business use cases, while Next Best Action strategies can load records, apply filters and rules, and map recommendation reasons. Prediction-based strategies can also map prediction models created with Einstein Prediction Builder.","For model-based recommendations, Consumer Goods Cloud supports data from the Consumer Goods schema, external point-of-sale sources, or uploaded CSV datasets. Prebuilt templates and recipes can generate training and scoring datasets, and Einstein Discovery models can predict outcomes such as revenue uplift or visit frequency. Prediction results can be written back to a custom object and mapped into a Next Best Action strategy. Sales managers can then create recommendation requests that run the strategy for each date in the requested interval."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.industries_einstein_ed_visit_recommendation.htm&language=en_US",connections:[{"planet":"visit_planning","desc":"Visit recommendations feed into visit plans"},{"planet":"accounts_stores","desc":"Store attributes drive recommendation scoring"}]},
    {id:"genai-health",name:"GenAI Health Assessments",icon:"\u{1F3E5}",desc:"GenAI Health Assessments in Consumer Goods Cloud evaluate managed-account performance by using historical orders, visits, customer tasks, product surveys, store audits, and asset audits. Assessments can identify highest- or lowest-performing products, brands, or categories and report total order revenue for a selected period. They can also surface challenges reflected in visit feedback, customer-reported tasks, and customer asset audits. Users access the generated assessment from Einstein Quick Insights on an Account record.",tags:[],docs:["Health assessment provides a comprehensive evaluation of an account without relying on inventory reconciliation. It can summarize sales performance, including total revenue and highest- or lowest-performing products, brands, or categories. It can also derive operational insights from store audits, product surveys, asset audits, overdue customer tasks, and visit notes. The documented prompt example can identify implicit challenges from visit notes, order delivery notes, invoice notes, and asset notes and suggest follow-up actions.","Administrators create a Record Summary prompt template for the Account object in Prompt Builder. The documented configuration uses the GenAIAccountSummaryHealthAssessmentData and GenAIAccountSummaryComplianceData invocable actions to supply account data to the prompt. Custom system settings can control the amount of historical visit, order, customer-task, and product-performance data retrieved by the invocable actions. After the prompt is activated and added to Einstein Quick Insights, users select it on an Account record and generate the health assessment."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.cg_concept_admin_einstein_embeddedai_cg_pilot.htm&language=en_US",connections:[{"planet":"visit_execution","desc":"Visit execution data feeds health assessment models"},{"planet":"analytics","desc":"Analytics data provides the metrics for AI assessment"}]},
    {id:"inventory-deviations",name:"Inventory Deviation Detection",icon:"\u{1F4E6}",desc:"Inventory Deviation Detection in Consumer Goods Cloud evaluates warehouse inventory discrepancies after inventory reconciliation. It identifies differences such as expected product checkout quantity versus actual checkout quantity. It can also identify products present on a truck that are missing from the check-in document. Users review the generated inventory-deviation information through Einstein Quick Insights on a Warehouse record.",tags:[],docs:["Inventory deviations are distinct from account health assessments and focus on inventory reconciliation data. Documented deviations include discrepancies between expected and actual checkout quantities and products on a truck that aren’t included in the check-in document. These results help users identify common reasons for inventory discrepancies. The inventory-reconciliation summary can consolidate data from multiple tours conducted from a warehouse.","Administrators create a Record Summary prompt template for the Warehouse object and use the GenAIWarehouseInventoryDeviations invocable action as a prompt resource. The documented prompt can request product categories with the highest discrepancies, root causes, driver performance, other useful insights, and follow-up actions. After activating the prompt and configuring Einstein Quick Insights on the Warehouse record page, users select the prompt and generate the deviation summary. The generated response can be reviewed and rated with feedback."],connections:[{"planet":"visit_execution","desc":"Inventory counts from visits feed deviation analysis"},{"planet":"van_sales","desc":"Warehouse inventory provides deviation baselines"}]},
    {id:"quick-insights",name:"Quick Insights",icon:"\u{1F4A1}",desc:"Quick Insights in Consumer Goods Cloud is the Einstein Quick Insights component used to display generative AI responses on supported record pages. Administrators can configure it on Account records for health assessments and on Warehouse records for inventory deviations. Users choose an available prompt, generate a response, and provide feedback. Account assessment and warehouse deviation prompts remain separate and evaluate different source data.",tags:[],docs:["Administrators add the Einstein Quick Insights component to Account and Warehouse Lightning record pages. In the component properties, they select Record Summary as the Prompt Template Type and choose the prompt templates that users can run. The page configuration must be saved and activated for the required Consumer Goods Cloud app. Users also need Einstein generative AI enabled and the documented permission sets assigned.","On an Account record, users select the health-assessment prompt in Quick Insights and choose Summarize to generate an account performance evaluation. On a Warehouse record, users select the inventory-deviation prompt and choose Summarize to review deviations after inventory reconciliation. The component presents the generated response and allows users to provide feedback. It does not make account health assessment dependent on warehouse or truck inventory reconciliation."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.cg_task_admin_configure_einstein_summary_component.htm&type=5&language=en_US",connections:[{"planet":"analytics","desc":"Quick Insights leverage the same data as analytics dashboards"},{"planet":"accounts_stores","desc":"Insights surface on account and store records"}]}
  ],
  dataFlow: ["Feed store attributes and targets into Einstein predictions.","Train and validate Einstein models with visit execution data.","Generate visit recommendations and apply them to visit planning priorities.","Evaluate account performance separately and present health assessments in Einstein Quick Insights.","Reconcile inventory, detect warehouse deviations, and use product velocity insights to inform van sales loading.","Analyze recommendations and execution outcomes on the data platform shared by Einstein and analytics."],
  connections: [{"planet":"visit_planning","desc":"Einstein recommendations influence visit planning priorities"},{"planet":"visit_execution","desc":"Visit execution data trains and validates Einstein models"},{"planet":"accounts_stores","desc":"Store attributes and targets feed Einstein predictions"},{"planet":"van_sales","desc":"Product velocity insights inform van sales loading"},{"planet":"analytics","desc":"Einstein and analytics share the same underlying data platform"}]
},

data_cloud: {
  packages: ["consumergoods"],
  name: "Data Cloud",
  icon: "\u{2601}\u{FE0F}",
  color: "#a3e635",
  description: "Data Cloud integration brings Consumer Goods Cloud account and store, product and assortment, visit execution, promotion, order, and related data into standardized Data Model Objects through the CG Cloud Data Kit. The unified data supports standard Data Cloud segmentation, with Apex and the segment members API used when segment memberships must be persisted in Consumer Goods Cloud records, and it provides the data foundation for CRM Analytics. For pricing, the pricing engine executes promotion-related conditions and can use a statistical accrual step; the documentation doesn’t identify a separate Accrual Engine or define claim reconciliation with accrual results. Data Cloud One shares selected DMO data spaces from a home org with a companion org without exposing the underlying DLOs or requiring another Data Cloud instance.",
  components: [
    {id:"data-kit",name:"CG Cloud Data Kit",icon:"\u{1F4E6}",desc:"The CG Cloud Data Kit supplies predefined Data Cloud components for Consumer Goods Cloud data. Separate unmanaged data kits support Retail Execution Base, Retail Execution Enhanced, and Trade Promotion Management, while Retail Execution Enhanced includes objects for both Retail Execution and Trade Promotion Management. After installation, administrators deploy the Consumer_Goods_Bundle data stream definition to ingest and map Consumer Goods Cloud data. Because the data kits contain overlapping components, only one can be installed at a time.",tags:["Assortment","AssortmentProduct","StoreAssortment"],docs:["Install the applicable CG Cloud Data Kit in the Salesforce org where Consumer Goods Cloud and Data Cloud are enabled. The supported packages cover Retail Execution Base, Retail Execution Enhanced, and Trade Promotion Management. Retail Execution Enhanced includes the objects of both Retail Execution and Trade Promotion Management and is the appropriate option when both sets of functionality are required. The packages are unmanaged and can’t be upgraded in place.","After installation, create Salesforce CRM data streams in Data Cloud and select Consumer_Goods_Bundle from the connected Consumer Goods Cloud org. The bundle is a Salesforce-defined data stream definition that includes mappings to the Data Cloud DMO structure. Select a data space, review the included fields, apply the documented data stream names and categories, and deploy the streams. When the streams become active, configure the remaining data lake objects and data transforms required by the selected data kit.","To replace or switch a data kit, first document customizations and remove deployed components and dependencies before uninstalling the existing package. A new data kit installation fails if another installed kit already provides a component with the same name. If dependencies prevent removal of a data kit, administrators must manually create the required data mappings. These requirements make data-kit selection and change management important parts of the deployment process."],connections:[{"planet":"tpm_master_data","desc":"Ingests account and product master data into DMOs"},{"planet":"products_assortments","desc":"Assortment data streams flow into Data Cloud"}]},
    {id:"dmo-mappings",name:"Data Model Objects",icon:"\u{1F5C3}\u{FE0F}",desc:"Data Model Objects provide the standardized Data Cloud representation of Consumer Goods Cloud data after data streams and mappings are deployed. The mappings cover accounts and retail stores, products and assortments, visits and retail visit KPIs, promotions, orders, and related records. Retail Execution Enhanced adds mappings for advanced orders, advanced promotions, tactics, product hierarchies, POS data, visit jobs, and account roles and relationships. This unified model supports segmentation and provides Consumer Goods Cloud data for CRM Analytics.",tags:["cgcloud__Account_Extension__c","cgcloud__Product_Hierarchy__c","cgcloud__Promotion__c","cgcloud__Tactic__c"],docs:["The CG Cloud Data Kit maps Consumer Goods Cloud data lake object attributes to Data Model Object attributes. Retail Execution Base includes mappings for Account, Address, Assortment, Assortment Product, In Store Location, Location, Product, Product Category, Promotion, Retail Store, Retail Store Group, Retail Visit KPI, Sales Order, Sales Order Product, Visit, and related assessment data. These mappings ingest store and account information, product and assortment assignments, order activity, promotion records, and visit execution results into standardized DMOs.","Retail Execution Enhanced extends the mappings with Consumer Goods Cloud managed-package data. Examples include Customer Extensions, Customer Relationship, Customer Trade Org Hierarchies, Advanced Orders and Advanced Order Items, Advanced Promotions, Tactics, Tactic Products, Product Hierarchies, POS records, Job Definition records, and Visit Jobs. Streaming or batch data transforms create supporting data lake objects for address components, account roles, promotion-account relationships, POS templates, tactic types, and visit jobs before mapping the results to DMOs.","The mapped Visit and Retail Visit KPI data includes visit status, planned and actual times, account and place references, compliance values, assessment definitions, products, promotions, and in-store locations. Product and assortment mappings preserve product assignments, validity periods, distribution status, facing values, and selling prices where supplied by the source objects. Promotion mappings include promotion dates, status, accounts, products, categories, offers, and tactic details. Together, these DMOs provide a consistent data foundation for segmentation and downstream CRM Analytics."],connections:[{"planet":"analytics","desc":"DMOs provide unified data layer for analytics and dashboards"}]},
    {id:"segmentation",name:"Account Segmentation",icon:"\u{1F3AF}",desc:"Account Segmentation uses standard Data Cloud segments built from Consumer Goods Cloud DMOs. Administrators select a DMO as the segment target and define filters from its available attributes, including account, retail store, product, visit, order, and promotion-related data available through the deployed mappings. Published segments update the corresponding Audience DMO at the selected activation target. When segment membership must be persisted in Consumer Goods Cloud, an Apex and API process can retrieve segment members and create or update the related custom records.",tags:["cgcloud__Account_Set__c"],docs:["Create a standard segment in Data Cloud with the visual builder and select the DMO on which the segment is built. The selected target determines which attributes are available as segment filters. For example, a segment can target Retail Store and filter stores by an attribute such as Delivery Method. Configure the data space, publishing method, and refresh schedule, and then save the segment.","After the segment is created, publish it to a Data Cloud activation target. When the segment is published, the activated records are written to the corresponding Audience DMO and can be reviewed in Data Explorer. Segment rules and properties can be edited after creation when the targeting criteria or business purpose changes. Consumer Goods Cloud promotion, account, store, product, visit, and order attributes mapped to DMOs can contribute to the available segmentation context.","To save segment results to Consumer Goods Cloud custom records, use Apex to call the segment members API endpoint and process the returned identifiers. The documented example retrieves account IDs, creates an Account Set when one doesn’t exist for the segment, adds new Account Set Account records, and deletes memberships that are no longer returned. The segment must have a successful status and at least one activation before this process runs. For large result sets, use a batch job because Apex governor limits apply."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.cg_concept_admin_customer_target_group_segmentation.htm&type=5&language=en_US",connections:[{"planet":"accounts_stores","desc":"Segmentation groups stores by behavior and attributes"},{"planet":"promotions","desc":"Segments define targeted promotion audiences"}]},
    {id:"accrual-engine",name:"Accrual Engine",icon:"\u{1F4B0}",desc:"The Accrual Engine component represents accrual handling within the documented Penny Perfect Pricing configuration, but the documentation doesn’t identify a separate engine by that name. The pricing engine executes the configured conditions in the ordered calculation steps of a Calculation Schema. A statistical calculation step can preserve a result without immediately changing the order item’s net price, and one type of statistical step is an accrual step. Promotion-related conditions can participate in pricing, while claim reconciliation is a connected claims process that isn’t defined by this Data Cloud or pricing-engine documentation.",tags:[],docs:["Penny Perfect Pricing uses a pricing engine to calculate order and order-item prices from configured pricing conditions. A Calculation Schema contains an ordered sequence of calculation steps, and each applicable step can be linked to a Pricing Condition Template that defines the condition behavior and how the required condition data is found. Pricing Condition Templates can represent prices, percentage or amount discounts, flat rates, subtotals, free goods, or user-exit behavior. The pricing engine executes the configured conditions in schema order to produce the calculation result.","A calculation step can be marked statistical when its result must remain available without being directly added to the final order-item total. Results from statistical steps can be referenced by subsequent calculation steps. One type of statistical step is an accrual step, used for an amount that is part of the calculation but doesn’t immediately change the net price shown to the customer. The documentation gives a marketing rebate or promotion intended for later deduction as an example and doesn’t describe a separate Accrual Engine.","Promotion data can influence pricing through Advanced Promotion records, promotion rewards, pricing conditions, and calculation steps. The pricing engine, rather than a separately documented accrual service, performs the configured calculation. The supplied help content doesn’t define a mechanism that reconciles claim records with accrual-step results. Any claim reconciliation therefore remains part of the connected claims process rather than a documented function of this component."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.tpm_concept_accruals_type.htm&type=5&language=en_US",connections:[{"planet":"promotions","desc":"Accruals calculated from promotion commitments"},{"planet":"claims","desc":"Accruals reconciled against actual claim settlements"}]},
    {id:"data-cloud-one",name:"Data Cloud One",icon:"\u{1F517}",desc:"Data Cloud One connects a primary Salesforce home org to a separate companion org. The companion org can access selected Data Model Object data from shared data spaces without requiring its own Data Cloud instance. Administrators create the connection in the home org, choose the data spaces to share, and then configure ingestion from the companion org. Companion-org users can view shared DMOs in Data Explorer but can’t view the underlying Data Lake Objects.",tags:[],docs:["The home org is the primary Salesforce org where Data Cloud is installed, and the companion org is a separate Enterprise Edition Salesforce org on the same instance. From Data Cloud One setup in the home org, an administrator authenticates to the companion org, assigns a unique connection name, and selects the data spaces to share. After the terms are accepted, the connection process begins. The applicable Consumer Goods Cloud data kit must already be installed and configured in the home org.","After the connection becomes active, configure a Salesforce CRM data stream in the home org that uses the companion org as its source. Select the companion-org object to ingest and assign the stream to a shared data space. Records created in the companion org then flow to the configured data space and can be verified in Data Explorer. Users in the companion org can see the resulting DMO data but not the underlying DLOs."],connections:[{"planet":"analytics","desc":"Companion orgs access shared analytics data"}]}
  ],
  dataFlow: ["Install one applicable CG Cloud Data Kit and connect the Consumer Goods Cloud org to Data Cloud.","Deploy Consumer_Goods_Bundle data streams and map account, store, product, assortment, visit, promotion, order, and related data to DMOs.","Transform supporting address, role, promotion, POS, and visit-job data where the selected data kit requires it.","Build and publish standard Data Cloud segments, and use Apex and the segment members API when memberships must update Consumer Goods Cloud records.","Execute configured promotion conditions and statistical accrual steps through the pricing engine; handle claim reconciliation in the connected claims process because no reconciliation mechanism is documented here.","Use the unified DMO data for CRM Analytics and share selected data spaces with companion orgs through Data Cloud One."],
  connections: [{"planet":"accounts_stores","desc":"Store and account data ingested into Data Cloud DMOs"},{"planet":"products_assortments","desc":"Product and assortment data mapped to DMOs"},{"planet":"visit_execution","desc":"Visit execution data flows into Data Cloud for unified analytics"},{"planet":"analytics","desc":"Data Cloud provides the data platform for CRM Analytics"},{"planet":"promotions","desc":"Promotion data feeds accrual calculations and segmentation"},{"planet":"claims","desc":"Claim data reconciled with accrual engine calculations"}]
}

};
